/* GERADO por scripts/dividir-dados.js — não edite à mão.
   A fonte editável continua sendo js/data*.js. */
registrarDetalhes({"ES-001":{"cognitivo":{"motivo":"Propriedade comparativa média × mediana — conceito central da estatística descritiva.","mede":"Medidas de posição e sensibilidade a outliers.","pegadinhaDesc":"Item correto; a inversão (média robusta) é a troca esperada em outras provas.","ondeErra":"Confunde qual das medidas 'sofre' com extremos.","palavraCritica":"não é influenciada pela magnitude","tecnica":"A mediana depende só da POSIÇÃO central; a média soma todos os valores — um bilionário na amostra arrasta a média, não a mediana.","regraMental":"Outlier bagunça a média; a mediana nem olha para ele."},"comentario":{"resolucao":"CERTO. A mediana é medida de posição baseada na ordem dos dados: valores extremos alteram no máximo qual observação ocupa o centro, mas não 'puxam' o resultado pela sua magnitude. A média, por incorporar todos os valores no numerador, é sensível a outliers.","fundamento":"Estatística descritiva — propriedades das medidas de tendência central.","macete":"Renda de bairro com um milionário: média mente, mediana conta a verdade.","erroComum":"Marcar E por achar que 'robusta' teria sentido técnico diverso.","comoBancaPensa":"Compara duas medidas irmãs — o formato favorito para futuras inversões."}},"ES-002":{"cognitivo":{"motivo":"O erro inferencial mais clássico da estatística aplicada.","mede":"Interpretação do coeficiente de Pearson (item 2.25 do edital).","pegadinhaDesc":"Converte associação estatística em relação causal.","ondeErra":"Traduz 'andam juntas' como 'uma causa a outra'.","palavraCritica":"correlação ≠ causalidade","tecnica":"r próximo de 1 indica forte associação LINEAR — que pode decorrer de coincidência, variável oculta (confundidora) ou causalidade reversa.","regraMental":"Sorvete e afogamentos se correlacionam — a causa é o verão, não o sorvete."},"comentario":{"resolucao":"ERRADO. O coeficiente de Pearson mede apenas a força e o sentido da associação linear entre variáveis. Correlação elevada não autoriza conclusão de causalidade: pode haver terceira variável influenciando ambas, relação inversa ou mero acaso. Causalidade exige desenho de estudo adequado (experimentos, controles).","fundamento":"Estatística — interpretação do coeficiente de correlação.","macete":"Pearson mostra a dança, não diz quem conduz.","erroComum":"Concluir 'X causa Y' de um r alto.","comoBancaPensa":"Frase tecnicamente vestida escondendo o salto lógico proibido."}},"ES-003":{"cognitivo":{"motivo":"Regra 68-95-99,7, item expresso do edital (2.27).","mede":"Propriedades da distribuição normal.","pegadinhaDesc":"Item correto; as trocas típicas são 95%↔99,7% ou 1↔2 desvios.","ondeErra":"Embaralha os pares percentual↔número de sigmas.","palavraCritica":"±2σ ↔ 95%","tecnica":"Grave a escada: ±1σ ≈ 68%; ±2σ ≈ 95%; ±3σ ≈ 99,7%.","regraMental":"68-95-99,7: um degrau por sigma."},"comentario":{"resolucao":"CERTO. Pela regra empírica da distribuição normal: cerca de 68% dos dados estão a ±1 desvio-padrão da média, 95% a ±2 e 99,7% a ±3. A assertiva pareia corretamente 95% com dois desvios.","fundamento":"Estatística — regra empírica (três sigmas) da distribuição normal.","macete":"Sequência mágica: 68 → 95 → 99,7.","erroComum":"Atribuir 95% a ±1σ ou 99% a ±2σ.","comoBancaPensa":"Três pares numéricos fixos = questão de conferência direta, feita para trocas."}},"ES-004":{"cognitivo":{"motivo":"Utilidade prática do CV — comparação entre séries heterogêneas.","mede":"Medidas de dispersão (item 2.24.4).","pegadinhaDesc":"Item conceitual correto; a troca clássica é inverter a razão (média/desvio).","ondeErra":"Confunde a fórmula ou nega a comparabilidade.","palavraCritica":"desvio ÷ média","tecnica":"CV = s/x̄ (geralmente ×100%): as unidades se cancelam, sobrando dispersão 'por unidade de média'.","regraMental":"CV compara alturas em metros com pesos em quilos — porque vira porcentagem pura."},"comentario":{"resolucao":"CERTO. CV = desvio-padrão ÷ média (frequentemente ×100). Por ser a razão de duas grandezas na mesma unidade, é adimensional — ideal para comparar variabilidades de variáveis com médias ou unidades distintas (ex.: dispersão de salários × dispersão de idades).","fundamento":"Estatística descritiva — medidas de dispersão relativa.","macete":"Quem tem maior CV é mais heterogêneo, não importa a unidade.","erroComum":"Inverter numerador e denominador da razão.","comoBancaPensa":"Definição + utilidade na mesma frase: dupla oportunidade de troca em provas futuras."}},"ES-005":{"cognitivo":{"motivo":"Definição formal de independência — base para Bayes e distribuições.","mede":"Conceito de independência (itens 2.18-2.19).","pegadinhaDesc":"Item correto; a confusão plantada em provas é independente × mutuamente excludente.","ondeErra":"Mistura independência (produto) com exclusão mútua (interseção vazia).","palavraCritica":"P(A∩B) = P(A)·P(B)","tecnica":"Independentes: um não altera a chance do outro. Excludentes: não podem ocorrer juntos — conceitos DIFERENTES.","regraMental":"Excludentes com probabilidade positiva nunca são independentes."},"comentario":{"resolucao":"CERTO. A definição de independência é exatamente P(A∩B) = P(A)×P(B) — equivalente a P(A|B) = P(A). Não confundir com eventos mutuamente excludentes, em que P(A∩B) = 0.","fundamento":"Teoria da probabilidade — axiomas e independência.","macete":"Independente multiplica; excludente soma (na união) e zera (na interseção).","erroComum":"Tratar 'não podem ocorrer juntos' como sinônimo de independência.","comoBancaPensa":"Definições vizinhas e trocáveis — decorou uma, a banca cobra a fronteira entre as duas."}},"ES-006":{"cognitivo":{"motivo":"Inversão espelhada das duas técnicas de amostragem por grupos.","mede":"Técnicas de amostragem (itens 2.28-2.29).","pegadinhaDesc":"As descrições estão corretas — com os rótulos trocados entre si.","ondeErra":"Reconhece as mecânicas, não confere o pareamento nome↔procedimento.","palavraCritica":"de cada estrato × grupos inteiros","tecnica":"ESTRATIFICADA: tira um pouco DE CADA estrato (todos os grupos participam). CONGLOMERADOS: sorteia GRUPOS inteiros (nem todos participam).","regraMental":"Estrato = fatia de todos. Conglomerado = pacote fechado sorteado."},"comentario":{"resolucao":"ERRADO. Está invertido. Na amostragem ESTRATIFICADA, dividem-se os elementos em estratos homogêneos e sorteiam-se elementos DENTRO DE CADA estrato. Na amostragem POR CONGLOMERADOS, sorteiam-se conglomerados (grupos) inteiros e examinam-se seus integrantes.","fundamento":"Técnicas de amostragem probabilística.","macete":"Pesquisa por bairros sorteando QUARTEIRÕES inteiros = conglomerado. Garantindo homens E mulheres na amostra = estrato.","erroComum":"Aceitar o item porque as duas mecânicas 'existem'.","comoBancaPensa":"Par espelhado de procedimentos — o mesmo molde de DA-005 e DH-005."}},"ES-007":{"cognitivo":{"motivo":"Definição nuclear de α — item 3.3 do edital.","mede":"Testes de hipóteses: significância e tipos de erro.","pegadinhaDesc":"Item correto; a troca padrão é atribuir α ao erro tipo II (β).","ondeErra":"Embaralha os dois tipos de erro.","palavraCritica":"rejeitar H0 verdadeira","tecnica":"Erro I: condenar inocente (rejeitar H0 verdadeira) = α. Erro II: absolver culpado (aceitar H0 falsa) = β. Potência = 1−β.","regraMental":"Analogia do júri: H0 é a inocência — erro tipo I é a condenação injusta."},"comentario":{"resolucao":"CERTO. O nível de significância (α) é, por definição, a probabilidade máxima tolerada de erro tipo I — rejeitar a hipótese nula sendo ela verdadeira. O erro tipo II (β) é o oposto: não rejeitar H0 falsa; a potência do teste é 1−β.","fundamento":"Inferência estatística — teoria dos testes de hipóteses.","macete":"α vem primeiro no alfabeto e no tipo de erro: tipo I.","erroComum":"Definir α como 'probabilidade de a hipótese ser verdadeira' (interpretação incorreta).","comoBancaPensa":"Dupla de erros espelhados (I × II) = próxima inversão já contratada."}},"ES-008":{"cognitivo":{"motivo":"Conceito central de avaliação de modelos — item 4 de Análise de Dados.","mede":"Fontes de erro em modelos preditivos.","pegadinhaDesc":"Item correto; a banca tende a trocar por underfitting ou dizer que overfitting erra 'também no treino'.","ondeErra":"Confunde over (decora) com under (nem aprende).","palavraCritica":"ótimo no treino, ruim no novo","tecnica":"Overfitting = decorou a prova do ano passado. Underfitting = não estudou nem o básico. Regularização/validação cruzada combatem o primeiro.","regraMental":"Decorar ≠ aprender — modelo que decora falha no mundo real."},"comentario":{"resolucao":"CERTO. Overfitting é o sobreajuste: o modelo captura ruído e idiossincrasias do conjunto de treinamento, minimizando o erro ali, mas com erro elevado em dados não vistos (baixa generalização). Mitigações: regularização, validação cruzada, mais dados, simplificação do modelo.","fundamento":"Machine learning — viés × variância, validação de modelos.","macete":"Treino 99%, produção 60% = cheiro clássico de overfitting.","erroComum":"Chamar de overfitting o modelo que já erra no próprio treino (isso é underfitting).","comoBancaPensa":"Par over/under = mais um espelho pronto para inversão em prova."}},"ES-009":{"cognitivo":{"motivo":"Fronteira supervisionado × não supervisionado — base da mineração de dados.","mede":"Tarefas de mineração (item 2 de Análise de Dados).","pegadinhaDesc":"Atribui à clusterização a exigência de rótulos, própria da CLASSIFICAÇÃO.","ondeErra":"Confunde agrupar (descobrir grupos) com classificar (prever classe conhecida).","palavraCritica":"não supervisionado","tecnica":"CLASSIFICAÇÃO: rótulos prévios (supervisionado). CLUSTERIZAÇÃO: descobre grupos por similaridade, SEM rótulos (não supervisionado).","regraMental":"Cluster procura padrões que ninguém etiquetou."},"comentario":{"resolucao":"ERRADO. A clusterização é técnica de aprendizado NÃO SUPERVISIONADO: agrupa observações por similaridade sem qualquer rótulo prévio (ex.: k-means agrupando ocorrências criminais por padrão espacial). Quem exige dados rotulados é a classificação (supervisionada), como o Naive Bayes.","fundamento":"Mineração de dados — paradigmas de aprendizado.","macete":"Tem gabarito no treino? Supervisionado. Não tem? Cluster/associação.","erroComum":"Rotular toda mineração como supervisionada.","comoBancaPensa":"Vocabulário técnico do edital novo — quem só decorou nomes cai na troca de paradigma."}},"ES-010":{"cognitivo":{"motivo":"Cobrar o conceito e a aplicação do teorema de Bayes.","mede":"Probabilidade condicional e regra de Bayes (item 2 do edital de Estatística).","pegadinhaDesc":"A banca costuma inverter a priori × a posteriori ou negar a atualização pela evidência.","ondeErra":"Confunde a probabilidade inicial (a priori) com a atualizada (a posteriori).","palavraCritica":"atualizar à luz de nova evidência","tecnica":"Bayes: P(H|E) = P(E|H)·P(H)/P(E). A posteriori = verossimilhança × a priori ÷ evidência.","regraMental":"A priori = antes da evidência. A posteriori = depois de observar a evidência."},"comentario":{"resolucao":"CERTO. O teorema de Bayes atualiza a crença sobre uma hipótese H após observar a evidência E: P(H|E) = P(E|H)·P(H)/P(E). Combina a probabilidade a priori P(H) com a verossimilhança P(E|H) para obter a probabilidade a posteriori. É base de raciocínio investigativo e de modelos como o Naive Bayes.","fundamento":"Teoria da probabilidade — teorema de Bayes.","macete":"Bayes = 'revisar a aposta' quando surge uma pista nova.","erroComum":"Inverter a priori (antes) com a posteriori (depois).","comoBancaPensa":"Bayes é citado nominalmente no edital — cobrança conceitual e aplicada."}},"ES-011":{"cognitivo":{"motivo":"Cobrar o enunciado do Teorema Central do Limite.","mede":"Distribuições amostrais / TCL (item 2 do edital de Estatística).","pegadinhaDesc":"A banca costuma exigir que a população seja normal (o TCL justamente dispensa isso).","ondeErra":"Acha que a população precisa ser normal para a média amostral ser normal.","palavraCritica":"independentemente da distribuição da população","tecnica":"TCL: com n grande, a média amostral tende à normal, mesmo se a população não for normal.","regraMental":"TCL: 'a média se comporta como normal' quando n cresce — não importa a forma da população."},"comentario":{"resolucao":"CERTO. O Teorema Central do Limite afirma que a distribuição da média amostral tende à normal conforme n cresce, qualquer que seja a distribuição da população de origem (com média e variância finitas). É o que fundamenta a inferência sobre médias.","fundamento":"Estatística — Teorema Central do Limite.","macete":"TCL = 'com amostra grande, a média vira normal', não importa a população.","erroComum":"Exigir população normal (o TCL dispensa isso).","comoBancaPensa":"A independência em relação à distribuição populacional é o ponto-chave manipulado."}},"ES-012":{"cognitivo":{"motivo":"Distinguir aprendizado supervisionado de não supervisionado.","mede":"Técnicas de mineração / machine learning (item II do edital de Análise de Dados).","pegadinhaDesc":"A banca costuma classificar a clusterização como supervisionada ou a classificação como não supervisionada.","ondeErra":"Confunde clusterização (sem rótulo) com classificação (com rótulo).","palavraCritica":"clusterização = não supervisionado","tecnica":"Supervisionado: dados rotulados (classificação, regressão). Não supervisionado: sem rótulos (clusterização, associação).","regraMental":"Tem rótulo/resposta conhecida = supervisionado. Descobre grupos sozinho = não supervisionado."},"comentario":{"resolucao":"CERTO. A clusterização (análise de agrupamentos) é aprendizado NÃO supervisionado: agrupa observações semelhantes sem rótulos prévios. Já a classificação e a regressão são supervisionadas (usam dados rotulados/variável-alvo conhecida).","fundamento":"Fundamentos de machine learning — paradigmas de aprendizado.","macete":"Cluster = descobre grupos (sem rótulo). Classificação = prevê rótulo (supervisionado).","erroComum":"Trocar clusterização (não supervisionado) por classificação (supervisionado).","comoBancaPensa":"Paradigmas de aprendizado são cobrados trocando as técnicas."}},"ES-013":{"cognitivo":{"motivo":"Cobrar o conceito de overfitting e o papel da regularização.","mede":"Fontes de erro em modelos preditivos (item II do edital).","pegadinhaDesc":"A banca costuma inverter overfitting × underfitting ou dizer que o overfitting melhora a generalização.","ondeErra":"Confunde sobreajuste (treino) com subajuste (modelo simples demais).","palavraCritica":"ajuste excessivo ao treino / piora a generalização","tecnica":"Overfitting: ótimo no treino, ruim no teste. Underfitting: ruim nos dois. Regularização penaliza a complexidade.","regraMental":"Overfitting = 'decorou o treino'. Underfitting = 'não aprendeu'. Regularização = 'simplifica'."},"comentario":{"resolucao":"CERTO. No overfitting, o modelo memoriza o ruído dos dados de treino e generaliza mal em dados novos (bom no treino, ruim no teste). A regularização (ex.: L1/L2), a validação cruzada e mais dados ajudam a mitigar. O oposto é o underfitting (modelo simples demais).","fundamento":"Machine learning — viés/variância, overfitting, regularização.","macete":"Overfitting = decorou; underfitting = não aprendeu. Regularização controla a complexidade.","erroComum":"Inverter overfitting com underfitting.","comoBancaPensa":"Par overfitting × underfitting é cobrado por inversão."}},"ES-014":{"cognitivo":{"motivo":"Cobrar a sequência de fases do CRISP-DM.","mede":"Exploração de dados / modelo CRISP-DM (item II do edital).","pegadinhaDesc":"A banca costuma inverter a ordem das fases ou dizer que a modelagem consome mais tempo.","ondeErra":"Desconhece a sequência e o peso da preparação de dados.","palavraCritica":"preparação de dados = fase mais custosa","tecnica":"CRISP-DM: negócio → dados → preparação → modelagem → avaliação → implantação. Preparação costuma dominar o tempo.","regraMental":"Começa entendendo o NEGÓCIO. A PREPARAÇÃO dos dados é o gargalo de tempo."},"comentario":{"resolucao":"CERTO. O CRISP-DM tem seis fases: entendimento do negócio, entendimento dos dados, preparação dos dados, modelagem, avaliação e implantação. O entendimento do negócio antecede a preparação, e esta costuma ser a etapa mais demorada do processo.","fundamento":"Metodologia CRISP-DM (mineração de dados).","macete":"Ordem: Negócio → Dados → Preparação → Modelagem → Avaliação → Implantação.","erroComum":"Inverter a ordem das fases.","comoBancaPensa":"Sequência de fases é cobrada por troca de ordem."}},"ES-015":{"cognitivo":{"motivo":"Cobrar a diferença entre média e mediana e o efeito da assimetria.","mede":"Medidas de tendência central (item 2 do edital de Estatística).","pegadinhaDesc":"Absolutiza com 'sempre', ignorando distribuições assimétricas.","ondeErra":"Assume que média e mediana coincidem em todo conjunto.","palavraCritica":"sempre","tecnica":"Média e mediana só coincidem em distribuições simétricas; a média é sensível a outliers, a mediana não.","regraMental":"Dados assimétricos: média ≠ mediana. Outlier puxa a média, não a mediana."},"comentario":{"resolucao":"ERRADO. Média e mediana só coincidem em distribuições simétricas. Em conjuntos assimétricos (ou com valores extremos), elas diferem — a média é influenciada por outliers, ao passo que a mediana é resistente a eles.","fundamento":"Estatística descritiva — medidas de posição.","macete":"Salário com um bilionário na sala: a média dispara, a mediana quase não muda.","erroComum":"Achar que média e mediana são sempre iguais.","comoBancaPensa":"Termo absoluto ('sempre') aplicado a conceito que depende da simetria."}},"ES-016":{"cognitivo":{"motivo":"Cobrar a natureza não negativa do desvio padrão.","mede":"Medidas de dispersão (item 2 do edital).","pegadinhaDesc":"Sugere desvio padrão negativo, o que é impossível.","ondeErra":"Confunde a posição dos dados (abaixo da média) com o sinal da dispersão.","palavraCritica":"negativos","tecnica":"Desvio padrão é a raiz quadrada da variância (média dos quadrados) — sempre ≥ 0.","regraMental":"Variância e desvio padrão nunca são negativos. Zero só quando todos os valores são iguais."},"comentario":{"resolucao":"ERRADO. O desvio padrão é a raiz quadrada da variância, calculada a partir de desvios ELEVADOS AO QUADRADO; portanto, é sempre maior ou igual a zero, independentemente de os dados estarem acima ou abaixo da média. Só é zero quando não há variação.","fundamento":"Estatística descritiva — variância e desvio padrão.","macete":"Quadrado não é negativo → dispersão não é negativa.","erroComum":"Associar 'dados abaixo da média' a desvio negativo.","comoBancaPensa":"Cria uma propriedade impossível para a medida de dispersão."}},"ES-017":{"cognitivo":{"motivo":"Distinguir amostragem aleatória simples da estratificada.","mede":"Técnicas de amostragem (item 2 do edital).","pegadinhaDesc":"Atribui à aleatória simples características da estratificada e nega a equiprobabilidade.","ondeErra":"Confunde amostragem simples (mesma chance) com estratificada (por estratos).","palavraCritica":"probabilidade distinta (deveria ser igual)","tecnica":"Aleatória simples: todos com IGUAL probabilidade. Estratificada: divide em estratos e amostra dentro de cada.","regraMental":"Aleatória simples = mesma chance para todos. 'Estratos' é da estratificada."},"comentario":{"resolucao":"ERRADO. Na amostragem aleatória simples, todos os elementos da população têm IGUAL probabilidade de seleção. A menção a 'estratos mais representativos' descreve a amostragem estratificada, técnica distinta.","fundamento":"Estatística — técnicas de amostragem.","macete":"Simples = igual chance. Estratificada = por grupos (estratos).","erroComum":"Trocar aleatória simples por estratificada.","comoBancaPensa":"Mistura características de duas técnicas de amostragem."}},"ES-018":{"cognitivo":{"motivo":"Cobrar a aplicabilidade da moda a variáveis qualitativas.","mede":"Medidas de tendência central (item 2 do edital).","pegadinhaDesc":"Inverte: a moda é justamente a que se aplica a qualitativas.","ondeErra":"Confunde a moda (contagem) com média/mediana (exigem ordem/aritmética).","palavraCritica":"moda não pode em qualitativas (falso)","tecnica":"Moda: valor mais frequente — aplicável inclusive a variáveis qualitativas nominais. Média e mediana exigem dados numéricos/ordenáveis.","regraMental":"Moda serve para qualquer variável (até nominal). Média/mediana, só numéricas/ordenáveis."},"comentario":{"resolucao":"ERRADO. É o contrário: a MODA (valor/categoria mais frequente) é a única medida de tendência central aplicável a variáveis QUALITATIVAS nominais, pois independe de operações aritméticas. Média e mediana exigem dados quantitativos (ou pelo menos ordenáveis, no caso da mediana).","fundamento":"Estatística descritiva — medidas de posição.","macete":"Cor preferida da turma? Só a moda responde (qualitativa).","erroComum":"Achar que a moda não serve para qualitativas.","comoBancaPensa":"Inverte a única medida aplicável a variáveis qualitativas."}},"ES-019":{"cognitivo":{"motivo":"Cobrar o intervalo do coeficiente de Pearson (−1 a +1).","mede":"Coeficiente de correlação de Pearson (item 2 do edital).","pegadinhaDesc":"Admite valores acima de 1 para o coeficiente.","ondeErra":"Desconhece que Pearson está limitado a [−1, +1].","palavraCritica":"acima de um (impossível)","tecnica":"Pearson varia de −1 a +1. |r|=1: correlação linear perfeita; r=0: ausência de correlação linear.","regraMental":"Pearson vive entre −1 e +1. Nunca passa disso."},"comentario":{"resolucao":"ERRADO. O coeficiente de correlação de Pearson (r) está limitado ao intervalo [−1, +1]. Não assume valores acima de +1 nem abaixo de −1. |r| próximo de 1 indica correlação linear forte; r = 0 indica ausência de correlação linear.","fundamento":"Estatística — coeficiente de correlação de Pearson.","macete":"Pearson: de −1 a +1, sempre. Fora disso, é erro.","erroComum":"Admitir |r| > 1.","comoBancaPensa":"Extrapola o intervalo do coeficiente."}},"ES-020":{"cognitivo":{"motivo":"Cobrar a simetria da distribuição normal e a coincidência das três medidas.","mede":"Distribuição normal (item 2 do edital).","pegadinhaDesc":"Diz que a normal é assimétrica e que as três medidas diferem.","ondeErra":"Confunde a normal (simétrica) com distribuições assimétricas.","palavraCritica":"assimétrica / valores distintos (falso)","tecnica":"Na normal (simétrica), média = mediana = moda, coincidindo no centro.","regraMental":"Normal é simétrica: média = mediana = moda. Assimetria é o oposto."},"comentario":{"resolucao":"ERRADO. A distribuição normal é SIMÉTRICA em torno da média; nela, média, mediana e moda COINCIDEM (assumem o mesmo valor central). A afirmação de assimetria e de valores distintos é falsa.","fundamento":"Estatística — distribuição normal.","macete":"Normal = sino simétrico: média = mediana = moda.","erroComum":"Tratar a normal como assimétrica.","comoBancaPensa":"Nega a simetria característica da normal."}},"ES-021":{"cognitivo":{"motivo":"Cobrar o intervalo axiomático da probabilidade [0, 1].","mede":"Conceitos básicos de probabilidade (item 2 do edital).","pegadinhaDesc":"Admite probabilidade negativa para evento impossível.","ondeErra":"Confunde 'evento impossível' (probabilidade zero) com valor negativo.","palavraCritica":"negativos (impossível)","tecnica":"Axiomas de Kolmogorov: 0 ≤ P(A) ≤ 1. Evento impossível: P = 0. Evento certo: P = 1.","regraMental":"Probabilidade vai de 0 a 1. Impossível = 0, não negativo."},"comentario":{"resolucao":"ERRADO. Pela definição axiomática, a probabilidade de qualquer evento está entre 0 e 1 (0 ≤ P ≤ 1). Um evento impossível tem probabilidade ZERO — nunca negativa. Um evento certo tem probabilidade 1.","fundamento":"Teoria da probabilidade — axiomas de Kolmogorov.","macete":"Probabilidade: 0 a 1. Impossível = 0. Certo = 1.","erroComum":"Associar evento impossível a probabilidade negativa.","comoBancaPensa":"Viola o intervalo axiomático da probabilidade."}},"ES-022":{"cognitivo":{"motivo":"Reconhecer a comparação renda × movimentação como técnica investigativa do edital.","mede":"Comparação entre fluxos financeiros e capacidade econômica (item III do edital).","pegadinhaDesc":"A banca costuma negar a validade da técnica ou exigir prova pericial exclusiva.","ondeErra":"Subestima a análise comparativa como indício idôneo.","palavraCritica":"incompatibilidade patrimonial","tecnica":"Movimentação muito superior à renda declarada é red flag clássica de lavagem/ocultação patrimonial.","regraMental":"Movimentou 10x o que declarou? Indício forte de incompatibilidade patrimonial."},"comentario":{"resolucao":"CERTO. A confrontação entre a movimentação financeira e a renda declarada é técnica expressamente prevista no programa (“comparação entre fluxos financeiros e capacidade econômica declarada”) e constitui indício relevante de ocultação patrimonial, a ser corroborado por outros elementos.","fundamento":"Técnicas de análise financeira investigativa; Lei 9.613/1998.","macete":"Renda declarada muito menor que a movimentação = sinal de alerta.","erroComum":"Desconsiderar a análise comparativa como indício.","comoBancaPensa":"Cobra a aplicação prática de uma técnica listada no edital."}},"ES-023":{"cognitivo":{"motivo":"Distinguir baixa dispersão de dispersão nula.","mede":"Medidas de dispersão (item 2 do edital de Estatística).","pegadinhaDesc":"Confunde 'valores próximos' (desvio pequeno) com 'valores idênticos' (desvio zero).","ondeErra":"Assume que proximidade implica igualdade absoluta.","palavraCritica":"necessariamente zero (falso)","tecnica":"Desvio padrão é zero SOMENTE quando todos os valores são exatamente iguais. Valores próximos geram desvio pequeno, porém positivo.","regraMental":"Desvio zero = todos idênticos. Só 'parecidos' = desvio pequeno, mas maior que zero."},"comentario":{"resolucao":"ERRADO. O desvio padrão é igual a zero apenas quando TODOS os valores do conjunto são exatamente iguais. Valores meramente próximos entre si produzem desvio padrão pequeno, mas necessariamente positivo. A proximidade indica baixa dispersão, não dispersão nula.","fundamento":"Estatística descritiva — variância e desvio padrão.","macete":"Desvio zero só se todos os números forem idênticos. 'Parecido' não é 'igual'.","erroComum":"Concluir dispersão nula a partir de valores apenas próximos.","comoBancaPensa":"Termo absoluto ('necessariamente zero') sobre medida que exige igualdade exata."}},"ES-024":{"cognitivo":{"motivo":"Cobrar o cálculo e a interpretação do intervalo interquartil.","mede":"Estatística — medidas de dispersão.","pegadinhaDesc":"A banca troca a subtração pela soma dos quartis.","ondeErra":"Soma os quartis em vez de subtrair, inflando o resultado.","palavraCritica":"soma","tecnica":"IIQ = Q3 − Q1 = 65 − 45 = 20 (e não a soma, que daria 110). Mede a dispersão dos 50% centrais dos dados (entre o 25º e o 75º percentil).","regraMental":"Intervalo interquartil: sempre Q3 MENOS Q1, nunca soma."},"comentario":{"resolucao":"ERRADO. O intervalo interquartil é calculado por subtração, e não soma: IIQ = Q3 − Q1 = 65 − 45 = 20. O valor 110 corresponderia à soma dos quartis, o que não tem significado estatístico como medida de dispersão.","fundamento":"Estatística descritiva — medidas de dispersão (intervalo interquartil).","macete":"IIQ = Q3 − Q1. Sempre subtração, nunca soma.","erroComum":"Somar os quartis em vez de subtrair.","comoBancaPensa":"Troca a operação aritmética correta por outra plausível."}},"ES-025":{"cognitivo":{"motivo":"Cobrar o critério clássico (regra de Tukey) para identificação de outliers.","mede":"Estatística — detecção de valores atípicos.","pegadinhaDesc":"A banca pode trocar o multiplicador (1,5) ou o ponto de referência (Q3).","ondeErra":"Não sabe o valor do multiplicador ou calcula a partir da mediana.","palavraCritica":"1,5 vez","tecnica":"Limite superior = Q3 + 1,5×IIQ = 65 + 1,5×20 = 65 + 30 = 95. Valores acima de 95 são outliers superiores.","regraMental":"Outlier superior: Q3 + 1,5×IIQ. Aqui: 65 + 30 = 95."},"comentario":{"resolucao":"CERTO. Pelo critério usual (regra de Tukey), o limite superior para outliers é Q3 + 1,5×IIQ = 65 + 1,5×(65−45) = 65 + 30 = 95. Valores estritamente superiores a 95 são considerados atípicos.","fundamento":"Estatística descritiva — regra de Tukey para outliers.","macete":"Outlier superior = Q3 + 1,5×IIQ. Outlier inferior = Q1 − 1,5×IIQ.","erroComum":"Usar multiplicador diferente de 1,5 ou somar ao invés de partir de Q3.","comoBancaPensa":"Exige o cálculo completo da regra de Tukey."}},"ES-026":{"cognitivo":{"motivo":"Cobrar o axioma de que a soma das probabilidades no espaço amostral é 1.","mede":"Estatística — probabilidade e variáveis aleatórias.","pegadinhaDesc":"Item conceitual: a banca costuma testar se o candidato confunde amplitude de valores observados com espaço amostral completo.","ondeErra":"Acha que sempre sobra probabilidade fora do intervalo mínimo-máximo observado.","palavraCritica":"sempre igual a 1","tecnica":"Se o intervalo [mínimo, máximo] contém TODOS os valores já observados/possíveis da variável, a probabilidade de X estar nesse intervalo é 1 (evento certo), por definição de função de probabilidade.","regraMental":"P(mínimo ≤ X ≤ máximo) = 1 quando esse intervalo cobre todo o suporte da variável."},"comentario":{"resolucao":"CERTO. Por definição, se o intervalo entre o valor mínimo e o valor máximo observados contém todo o suporte da variável aleatória X (ou seja, todos os valores possíveis), a probabilidade de X pertencer a esse intervalo é igual a 1, já que a soma das probabilidades de todos os valores possíveis de uma variável aleatória é sempre 1 (axioma da probabilidade total).","fundamento":"Teoria da probabilidade — axiomas de Kolmogorov (soma das probabilidades = 1).","macete":"Todo o suporte da variável = evento certo = probabilidade 1.","erroComum":"Supor que há probabilidade fora do intervalo observado.","comoBancaPensa":"Testa a compreensão do conceito de espaço amostral completo."}},"ES-027":{"cognitivo":{"motivo":"Cobrar o cálculo do escore Z (padronização da normal).","mede":"Estatística — distribuição normal.","pegadinhaDesc":"A banca troca o resultado correto (2) por outro número plausível (4).","ondeErra":"Erra a conta ou aceita o resultado sem recalcular.","palavraCritica":"escore Z igual a 4","tecnica":"Z = (X − μ) / σ = (121 − 85) / 18 = 36 / 18 = 2, e não 4.","regraMental":"Z = (valor − média) / desvio padrão. Sempre refaça a conta."},"comentario":{"resolucao":"ERRADO. O escore Z correto é Z = (X − μ) / σ = (121 − 85) / 18 = 36 / 18 = 2, e não 4. O valor 121 km/h está 2 desvios padrão acima da média, não 4.","fundamento":"Estatística — padronização da distribuição normal (escore Z).","macete":"Z = (X − média) / desvio padrão.","erroComum":"Aceitar o número da assertiva sem refazer o cálculo.","comoBancaPensa":"Troca o resultado numérico correto por outro plausível."}},"ES-028":{"cognitivo":{"motivo":"Cobrar a ordem correta das etapas do ETL.","mede":"Análise de dados — integração e tratamento de dados.","pegadinhaDesc":"A banca pode inverter a ordem (transformar antes de extrair), o que não faz sentido operacional.","ondeErra":"Aceita a inversão da ordem sem perceber o absurdo lógico.","palavraCritica":"extração ... antecede a transformação","tecnica":"ETL = Extract (extrair da fonte) → Transform (limpar/padronizar) → Load (carregar no destino). A extração é sempre a primeira etapa.","regraMental":"ETL: primeiro extrai, depois transforma, por último carrega."},"comentario":{"resolucao":"CERTO. No processo de ETL, a extração (Extract) dos dados de suas fontes de origem é a primeira etapa, antecedendo a transformação (Transform) — em que os dados são padronizados, limpos e enriquecidos — que, por sua vez, antecede o carregamento (Load) no ambiente de destino.","fundamento":"Análise de dados — processos de ETL (Extract, Transform, Load).","macete":"ETL: a ordem das letras é a ordem das etapas.","erroComum":"Inverter a ordem, transformando antes de extrair.","comoBancaPensa":"Testa se o candidato decorou a sigla sem entender o processo."}},"ES-029":{"cognitivo":{"motivo":"Cobrar a finalidade correta de cada biblioteca Python.","mede":"Análise de dados — ferramentas de ciência de dados.","pegadinhaDesc":"A banca inverte as finalidades das duas bibliotecas.","ondeErra":"Aceita a troca sem perceber a inversão de atribuições.","palavraCritica":"Pandas: DataFrame/Series. Sklearn: modelos de ML.","tecnica":"Pandas: manipulação/análise de dados tabulares (DataFrame, Series). Scikit-learn: construção e avaliação de modelos de machine learning (classificação, regressão, clusterização). O enunciado inverteu as duas.","regraMental":"Pandas organiza a tabela. Sklearn treina o modelo."},"comentario":{"resolucao":"ERRADO. As atribuições foram invertidas. O Pandas é a biblioteca voltada à manipulação e análise de dados estruturados, com as estruturas DataFrame e Series. O Scikit-learn (sklearn) é a biblioteca de referência para criação, treinamento e avaliação de modelos de aprendizado de máquina.","fundamento":"Análise de dados — bibliotecas Python (Pandas, Scikit-learn).","macete":"Pandas = tabela (DataFrame/Series). Sklearn = machine learning.","erroComum":"Não perceber a inversão de finalidades entre as duas bibliotecas.","comoBancaPensa":"Troca atribuições entre ferramentas conhecidas."}},"ES-030":{"cognitivo":{"motivo":"Cobrar a distinção entre aprendizado supervisionado e não supervisionado.","mede":"Análise de dados — mineração de dados.","pegadinhaDesc":"Troca a natureza da clusterização (não supervisionada) por supervisionada.","ondeErra":"Confunde clusterização (sem rótulos) com classificação (com rótulos).","palavraCritica":"aprendizado supervisionado ... rótulos previamente definidos","tecnica":"Clusterização é técnica de aprendizado NÃO supervisionado: agrupa observações por similaridade SEM rótulos prévios. Classificação (com rótulos) é que é supervisionada.","regraMental":"Clusterização: sem rótulo, não supervisionado. Classificação: com rótulo, supervisionado."},"comentario":{"resolucao":"ERRADO. A análise de agrupamentos (clusterização) é uma técnica de aprendizado NÃO supervisionado, que identifica grupos (clusters) de observações semelhantes entre si sem que existam rótulos ou categorias previamente definidas nos dados. A exigência de rótulos é característica da classificação, técnica supervisionada.","fundamento":"Mineração de dados — aprendizado supervisionado × não supervisionado.","macete":"Sem rótulo = não supervisionado = clusterização.","erroComum":"Trocar clusterização por classificação.","comoBancaPensa":"Inverte a natureza da técnica de aprendizado."}},"ES-031":{"cognitivo":{"motivo":"Cobrar a premissa 'ingênua' (naive) de independência condicional do algoritmo.","mede":"Machine Learning — classificador Naive Bayes.","pegadinhaDesc":"A banca pode negar a robustez prática do algoritmo apesar da premissa irrealista.","ondeErra":"Nega que o algoritmo funcione bem apesar da premissa simplificadora.","palavraCritica":"condicionalmente independentes","tecnica":"O Naive Bayes assume independência condicional dos atributos dado a classe (daí o nome 'naive'/ingênuo). Apesar de essa premissa raramente se sustentar na prática, o algoritmo é conhecido por bom desempenho empírico em muitas aplicações (ex.: filtros de spam).","regraMental":"Naive Bayes: independência condicional (premissa simplificada) + bom desempenho prático mesmo assim."},"comentario":{"resolucao":"CERTO. O Naive Bayes baseia-se no teorema de Bayes e assume que os atributos são condicionalmente independentes dado o valor da classe. Embora essa premissa 'ingênua' raramente reflita a realidade dos dados, o algoritmo é amplamente reconhecido por apresentar bom desempenho prático em diversas aplicações, como filtros antispam.","fundamento":"Machine Learning — classificador Naive Bayes (teorema de Bayes).","macete":"Naive = ingênuo = assume independência condicional entre atributos.","erroComum":"Achar que a premissa irrealista invalida o desempenho prático.","comoBancaPensa":"Testa o entendimento da premissa e da robustez empírica do modelo."}},"ES-032":{"cognitivo":{"motivo":"Cobrar o conceito de n-gramas em PLN.","mede":"Análise de dados — Processamento de Linguagem Natural.","pegadinhaDesc":"A banca inverte as definições de unigrama e bigrama.","ondeErra":"Aceita a troca sem perceber a inversão das quantidades.","palavraCritica":"unigrama: 1 item. Bigrama: 2 itens.","tecnica":"N-gramas são sequências contíguas de N itens de um texto. Unigrama (N=1): um único item. Bigrama (N=2): dois itens consecutivos. O enunciado inverteu as duas definições.","regraMental":"N-grama: N indica a quantidade de itens na sequência contígua."},"comentario":{"resolucao":"ERRADO. As definições foram invertidas. O unigrama corresponde a uma sequência de um único item (n=1), e o bigrama, a uma sequência de dois itens consecutivos (n=2) — e não o contrário.","fundamento":"Análise de dados — Processamento de Linguagem Natural (n-gramas).","macete":"Unigrama=1, bigrama=2, trigrama=3 itens.","erroComum":"Não perceber a inversão entre unigrama e bigrama.","comoBancaPensa":"Item de fixação conceitual sobre representação textual, com troca proposital das quantidades."}},"ES-033":{"cognitivo":{"motivo":"Cobrar a distinção entre overfitting e underfitting.","mede":"Machine Learning — validação e avaliação de modelos.","pegadinhaDesc":"A banca inverte os dois conceitos.","ondeErra":"Aceita a troca sem perceber a inversão entre os dois termos.","palavraCritica":"overfitting: excesso de ajuste. Underfitting: falta de ajuste.","tecnica":"Overfitting: modelo 'decora' o treino (ruído incluído), generaliza mal. Underfitting: modelo simples demais, nem no treino capta o padrão real. O enunciado trocou os dois nomes entre si.","regraMental":"Overfitting = ajuste demais (decora). Underfitting = ajuste de menos (não aprende)."},"comentario":{"resolucao":"ERRADO. Os conceitos foram invertidos. O overfitting (e não o underfitting) ocorre quando o modelo se ajusta em excesso aos dados de treinamento, capturando ruídos que comprometem sua generalização. O underfitting (e não o overfitting) caracteriza-se pela incapacidade do modelo de capturar os padrões subjacentes.","fundamento":"Machine Learning — validação e avaliação de modelos preditivos.","macete":"Overfitting: decorou demais. Underfitting: não aprendeu nada.","erroComum":"Não perceber a troca de nomes entre os dois conceitos.","comoBancaPensa":"Testa a distinção clássica entre os dois problemas de ajuste, invertendo os rótulos."}},"ES-034":{"cognitivo":{"motivo":"Cobrar a finalidade típica de cada formato de dados.","mede":"Análise de dados — formatos e tecnologias.","pegadinhaDesc":"A banca pode inverter as finalidades dos formatos.","ondeErra":"Troca CSV por XML/JSON quanto à estrutura hierárquica.","palavraCritica":"CSV: tabular simples. XML/JSON: hierárquico.","tecnica":"CSV: valores separados por vírgula, ideal para tabelas simples (linhas/colunas). XML e JSON: suportam estruturas aninhadas/hierárquicas (objetos dentro de objetos).","regraMental":"CSV = planilha simples. XML/JSON = dados aninhados."},"comentario":{"resolucao":"CERTO. O CSV é adequado para dados tabulares simples (linhas e colunas separadas por vírgula), enquanto XML e JSON permitem representar dados hierárquicos ou aninhados, com estruturas mais complexas de objetos e atributos.","fundamento":"Análise de dados — formatos e tecnologias (XML, JSON, CSV).","macete":"CSV: tabela simples. XML/JSON: estrutura aninhada.","erroComum":"Inverter as finalidades dos formatos.","comoBancaPensa":"Item de fixação sobre formatos de dados."}},"ES-035":{"cognitivo":{"motivo":"Cobrar a distinção entre estimação pontual e intervalar.","mede":"Estatística — inferência estatística.","pegadinhaDesc":"A banca inverte as definições dos dois tipos de estimação.","ondeErra":"Aceita a troca sem perceber a inversão dos nomes.","palavraCritica":"único valor ... intervalo ... nível de confiança","tecnica":"Estimação pontual: um único número (ex.: média amostral). Estimação intervalar: um intervalo (ex.: IC 95%) que, com determinado nível de confiança, contém o parâmetro real. O enunciado trocou os dois nomes entre si.","regraMental":"Pontual = um número. Intervalar = uma faixa + confiança."},"comentario":{"resolucao":"ERRADO. Os nomes foram invertidos. A estimação pontual (e não a intervalar) fornece um único valor como estimativa do parâmetro populacional. A estimação intervalar (e não a pontual) fornece um intervalo de valores plausíveis, associado a um nível de confiança.","fundamento":"Estatística — inferência estatística (estimação pontual e intervalar).","macete":"Pontual: um valor. Intervalar: faixa + confiança.","erroComum":"Não perceber a troca de nomes entre as duas formas de estimação.","comoBancaPensa":"Item de fixação conceitual em inferência, com troca proposital dos rótulos."}},"ES-036":{"cognitivo":{"motivo":"Cobrar o conceito de amostragem estratificada.","mede":"Estatística — técnicas de amostragem.","pegadinhaDesc":"A banca troca 'homogêneos' por 'heterogêneos' dentro do estrato.","ondeErra":"Aceita a troca sem perceber a inversão da lógica de homogeneidade interna.","palavraCritica":"internamente ... heterogêneos","tecnica":"Na amostragem estratificada, cada estrato deve ser internamente HOMOGÊNEO (indivíduos parecidos entre si) e os estratos entre si devem ser heterogêneos (diferentes uns dos outros) — o enunciado inverteu essa lógica.","regraMental":"Estratificada: dentro do estrato, parecido; entre estratos, diferente."},"comentario":{"resolucao":"ERRADO. A lógica foi invertida: na amostragem estratificada, cada estrato deve ser internamente HOMOGÊNEO (e não heterogêneo), com elementos semelhantes entre si quanto a alguma característica relevante, enquanto os estratos entre si devem ser heterogêneos.","fundamento":"Estatística — técnicas de amostragem (amostragem estratificada).","macete":"Estrato: homogêneo por dentro, heterogêneo entre estratos.","erroComum":"Não perceber a inversão da lógica de homogeneidade.","comoBancaPensa":"Item de fixação sobre a técnica de amostragem, com troca proposital do termo-chave."}},"ES-037":{"cognitivo":{"motivo":"Cobrar a relação entre média, mediana e tipo de assimetria.","mede":"Estatística — medidas de assimetria.","pegadinhaDesc":"A banca pode inverter a relação (positiva × negativa).","ondeErra":"Troca assimetria negativa por positiva.","palavraCritica":"mediana superior à média ... assimetria negativa","tecnica":"Assimetria negativa (à esquerda): média < mediana < moda, com cauda alongada à esquerda (valores menores 'puxando' a média para baixo).","regraMental":"Média menor que a mediana = assimetria negativa (cauda à esquerda)."},"comentario":{"resolucao":"CERTO. Quando a mediana é superior à média aritmética, a distribuição apresenta assimetria negativa (à esquerda): valores extremos menores 'puxam' a média para baixo, gerando uma cauda mais alongada nessa direção.","fundamento":"Estatística descritiva — medidas de assimetria.","macete":"Média < mediana → assimetria negativa (cauda à esquerda).","erroComum":"Inverter a direção da assimetria.","comoBancaPensa":"Testa a relação entre as três medidas de tendência central."}},"ES-038":{"cognitivo":{"motivo":"Cobrar a relação hierárquica correta entre IA, Machine Learning, redes neurais e LLMs.","mede":"Inteligência Artificial — fundamentos conceituais (hierarquia IA/ML/redes neurais/LLMs).","pegadinhaDesc":"A banca pode tratar os três conceitos como sinônimos ou inverter a relação de continência entre eles.","ondeErra":"Confunde ML, redes neurais e LLMs como se fossem a mesma coisa, ignorando que ocupam níveis distintos.","palavraCritica":"campo ... técnica ... arquiteturas neurais profundas","tecnica":"A relação é de continência: Inteligência Artificial (campo mais amplo) contém o Machine Learning (aprendizado a partir de dados), que utiliza, entre outras técnicas, as redes neurais artificiais; os LLMs são um tipo específico de rede neural profunda, treinada em larga escala para linguagem natural.","regraMental":"IA ⊃ Machine Learning ⊃ Redes Neurais ⊃ LLMs — cada conceito está 'dentro' do anterior."},"comentario":{"resolucao":"CERTO. A afirmação descreve corretamente a relação hierárquica entre os conceitos: Machine Learning é o campo da IA voltado ao aprendizado de padrões a partir de dados; as redes neurais são uma das técnicas utilizadas dentro desse campo; e os LLMs são modelos baseados em arquiteturas neurais profundas, treinados em larga escala para processar e gerar linguagem natural.","fundamento":"Doutrina de Inteligência Artificial — taxonomia e hierarquia conceitual (IA, ML, redes neurais, LLMs).","macete":"Pense em círculos concêntricos: IA por fora, depois ML, depois redes neurais, depois LLMs.","erroComum":"Tratar Machine Learning, redes neurais e LLMs como sinônimos intercambiáveis.","comoBancaPensa":"Item 'limpo', com a relação hierárquica descrita de forma tecnicamente precisa."}},"ES-039":{"cognitivo":{"motivo":"Cobrar, na forma invertida, que o Machine Learning generaliza a partir de dados e que redes neurais podem ter múltiplas camadas.","mede":"Inteligência Artificial — fundamentos conceituais (Machine Learning e redes neurais).","pegadinhaDesc":"A banca nega a capacidade de generalização do ML e simplifica indevidamente as redes neurais.","ondeErra":"Confunde Machine Learning com sistemas de regras fixas (IA simbólica clássica), ignorando sua capacidade de aprender e generalizar.","palavraCritica":"exclusivamente ... apenas por uma única camada","tecnica":"O Machine Learning é definido justamente pela capacidade de aprender padrões e generalizar a partir de dados, sem ser programado com regras fixas para cada situação. Além disso, redes neurais podem ter múltiplas camadas intermediárias (redes profundas) com funções de ativação não lineares, o que lhes confere maior poder de representação.","regraMental":"ML generaliza a partir de dados; redes neurais podem ter várias camadas com ativação não linear."},"comentario":{"resolucao":"ERRADO. O Machine Learning é definido pela capacidade de aprender padrões e generalizar a partir de dados, e não por regras fixas e determinísticas — essa última característica é mais próxima da IA simbólica clássica. Além disso, redes neurais artificiais podem possuir múltiplas camadas intermediárias e funções de ativação não lineares.","fundamento":"Doutrina de Inteligência Artificial — fundamentos conceituais (Machine Learning e redes neurais).","macete":"'Exclusivamente' e 'apenas' são bandeiras vermelhas em itens de IA.","erroComum":"Confundir Machine Learning com sistemas de regras fixas.","comoBancaPensa":"Combina duas palavras absolutas em uma única assertiva para reforçar o erro."}},"ES-040":{"cognitivo":{"motivo":"Cobrar o funcionamento técnico correto dos LLMs: previsão estatística da próxima palavra.","mede":"Inteligência Artificial — funcionamento dos modelos de linguagem (LLMs).","pegadinhaDesc":"A banca pode atribuir aos LLMs compreensão semântica real, ao invés de previsão estatística.","ondeErra":"Presume que o LLM 'entende' o significado do texto, quando na verdade modela relações probabilísticas entre palavras.","palavraCritica":"previsão estatística da sequência de palavras mais provável","tecnica":"Os LLMs, treinados com grandes volumes de texto por meio de redes neurais profundas, geram respostas prevendo, a cada passo, qual é a próxima palavra (ou token) mais provável, com base nos padrões estatísticos aprendidos durante o treinamento — não há compreensão semântica no sentido humano.","regraMental":"LLM não 'entende' — ele prevê a próxima palavra mais provável, estatisticamente."},"comentario":{"resolucao":"CERTO. Os LLMs constroem suas respostas por meio da previsão estatística da sequência de palavras mais provável, com base nos padrões aprendidos a partir de grandes volumes de dados textuais durante o treinamento — funcionamento fundamentalmente estatístico, e não baseado em compreensão semântica plena.","fundamento":"Doutrina de Inteligência Artificial — funcionamento técnico dos modelos de linguagem de grande porte (LLMs).","macete":"LLM = prevê a próxima palavra mais provável, com base no que aprendeu no treinamento.","erroComum":"Atribuir aos LLMs uma compreensão semântica equivalente à humana.","comoBancaPensa":"Item 'limpo' e tecnicamente correto sobre o mecanismo estatístico central dos LLMs."}},"ES-041":{"cognitivo":{"motivo":"Cobrar, na forma invertida, que os LLMs não têm consciência humana nem respostas totalmente determinísticas.","mede":"Inteligência Artificial — funcionamento e limitações dos LLMs.","pegadinhaDesc":"A banca atribui aos LLMs características humanas (consciência) e uma rigidez (determinismo total) que não possuem.","ondeErra":"Superestima a capacidade cognitiva dos LLMs, tratando-os como equivalentes à mente humana.","palavraCritica":"compreensão semântica plena ... totalmente determinísticas","tecnica":"Os LLMs não possuem consciência nem compreensão semântica equivalente à humana — eles modelam relações estatísticas entre palavras. Além disso, suas respostas variam conforme o contexto e os parâmetros de geração (como a 'temperatura'), não sendo totalmente determinísticas e invariáveis.","regraMental":"LLM não tem consciência humana, e suas respostas variam conforme o contexto — nunca são 'totalmente' fixas."},"comentario":{"resolucao":"ERRADO. Os LLMs não possuem compreensão semântica nem consciência contextual equivalentes à cognição humana — seu funcionamento é estatístico. Além disso, suas respostas podem variar conforme o contexto e os parâmetros de geração, não sendo totalmente determinísticas e invariáveis.","fundamento":"Doutrina de Inteligência Artificial — limitações dos modelos de linguagem de grande porte (LLMs).","macete":"LLM não tem consciência humana, nem respostas 100% fixas.","erroComum":"Humanizar excessivamente o funcionamento dos LLMs.","comoBancaPensa":"Combina duas afirmações absolutas e exageradas sobre a capacidade cognitiva dos LLMs."}},"ES-042":{"cognitivo":{"motivo":"Cobrar a característica central da IA generativa: criação de conteúdo inédito a partir de LLMs.","mede":"Inteligência Artificial — Inteligência Artificial Generativa (IAG).","pegadinhaDesc":"A banca pode negar a capacidade de criação de conteúdo inédito ou associar essas plataformas a outra tecnologia (ex.: segurança de rede).","ondeErra":"Confunde IA generativa com outras áreas de TI (redes, segurança, armazenamento).","palavraCritica":"criar conteúdos inéditos","tecnica":"A IA Generativa (IAG) é o subcampo da IA voltado à criação de conteúdo original — textos, imagens, músicas, códigos — sendo que plataformas amplamente conhecidas, como ChatGPT e DeepSeek, utilizam Modelos de Linguagem de Grande Porte (LLMs) como base tecnológica.","regraMental":"IA Generativa = GERA conteúdo novo. ChatGPT/DeepSeek = LLMs por trás da geração."},"comentario":{"resolucao":"CERTO. A IA Generativa é definida pela capacidade de criar conteúdos inéditos — textos, imagens, músicas e códigos —, sendo que plataformas amplamente utilizadas, como o ChatGPT e o DeepSeek, têm seu funcionamento baseado em Modelos de Linguagem de Grande Porte (LLMs).","fundamento":"Doutrina de Inteligência Artificial — Inteligência Artificial Generativa (IAG).","macete":"IA Generativa = cria conteúdo novo (texto, imagem, áudio, código).","erroComum":"Associar a IA generativa a funções de segurança de rede ou armazenamento, sem relação com o tema.","comoBancaPensa":"Item 'limpo' com a definição correta e exemplos reais e coerentes de plataformas."}},"ES-043":{"cognitivo":{"motivo":"Cobrar, na forma invertida, que a IA generativa cria conteúdo inédito e depende de treinamento prévio.","mede":"Inteligência Artificial — Inteligência Artificial Generativa (IAG).","pegadinhaDesc":"A banca nega a capacidade central da IA generativa e restringe seu uso a um único contexto (jogos).","ondeErra":"Aceita múltiplas negações absolutas na mesma assertiva sem perceber que contrariam a definição básica do conceito.","palavraCritica":"incapaz ... exclusivamente ... sem qualquer treinamento prévio","tecnica":"A IA generativa é justamente capaz de produzir textos e outros conteúdos inéditos, com aplicações que vão muito além de jogos eletrônicos (produtividade, educação, programação, arte), e depende de treinamento prévio extenso com grandes volumes de dados para funcionar.","regraMental":"IA generativa: cria conteúdo inédito + sempre depende de treinamento prévio."},"comentario":{"resolucao":"ERRADO. A IA generativa é justamente capaz de produzir textos e outros conteúdos inéditos, com aplicações muito além do entretenimento, e depende de treinamento prévio extenso com grandes volumes de dados — a assertiva nega, ao mesmo tempo, três características básicas e corretas do conceito.","fundamento":"Doutrina de Inteligência Artificial — Inteligência Artificial Generativa (IAG).","macete":"IA generativa sempre precisa de treinamento prévio e não se restringe a jogos.","erroComum":"Aceitar múltiplas negações absolutas empilhadas na mesma assertiva.","comoBancaPensa":"Empilha três negações absolutas na mesma frase, todas contrárias à definição do conceito."}},"ES-044":{"cognitivo":{"motivo":"Cobrar que ferramentas como o Copilot acessam contexto de documentos, mas ainda assim exigem revisão humana.","mede":"Inteligência Artificial — IA generativa integrada a suítes de produtividade.","pegadinhaDesc":"A banca pode negar o acesso a contexto ou dispensar a revisão humana dos resultados.","ondeErra":"Acha que, por ser uma ferramenta integrada, o Copilot não acessa nenhum contexto do usuário, ou que seus resultados dispensam checagem.","palavraCritica":"acesso ao contexto ... continuam exigindo revisão humana","tecnica":"Ferramentas de IA generativa integradas a suítes de produtividade, como o Copilot, têm acesso ao contexto de documentos e dados do usuário (por meio de integrações como o Microsoft Graph) para gerar sugestões mais relevantes — mas isso não elimina a necessidade de revisão humana dos resultados, já que os modelos podem produzir erros ou 'alucinações'.","regraMental":"Copilot acessa contexto do usuário, mas resultado sempre precisa de revisão humana."},"comentario":{"resolucao":"CERTO. Ferramentas de IA generativa integradas a suítes de produtividade, como o Copilot, realmente têm acesso ao contexto de documentos do usuário para gerar respostas mais relevantes, mas isso não dispensa a revisão humana dos resultados, uma vez que tais modelos não são treinados exclusivamente com informações integralmente verificadas.","fundamento":"Doutrina de Inteligência Artificial — IA generativa integrada a suítes de produtividade (Copilot).","macete":"Copilot vê o contexto do documento, mas o resultado sempre precisa de revisão humana.","erroComum":"Achar que ferramentas integradas não acessam contexto algum, ou que dispensam revisão humana.","comoBancaPensa":"Testa duas características simultaneamente corretas sobre uma mesma ferramenta."}},"ES-045":{"cognitivo":{"motivo":"Cobrar, na forma invertida, que ferramentas como o Copilot acessam contexto e ainda exigem revisão humana.","mede":"Inteligência Artificial — IA generativa integrada a suítes de produtividade.","pegadinhaDesc":"A banca nega o acesso a contexto de documentos e, de forma incoerente, usa essa negativa para dispensar a revisão humana.","ondeErra":"Aceita a premissa falsa (sem acesso a contexto) e a conclusão falsa (sem necessidade de revisão) em cadeia.","palavraCritica":"não têm acesso a nenhum tipo de contexto ... dispensam qualquer revisão","tecnica":"Ferramentas como o Copilot efetivamente acessam o contexto de documentos do usuário para gerar sugestões mais relevantes — e, ainda assim, seus resultados continuam exigindo revisão humana, pois esses modelos não são infalíveis nem treinados exclusivamente com dados integralmente verificados.","regraMental":"Copilot: acessa contexto, SIM. Dispensa revisão humana, NÃO."},"comentario":{"resolucao":"ERRADO. Ferramentas de IA generativa integradas a suítes de produtividade, como o Copilot, efetivamente têm acesso ao contexto de documentos do usuário — e, mesmo assim, seus resultados continuam exigindo revisão humana, já que os modelos não são infalíveis.","fundamento":"Doutrina de Inteligência Artificial — IA generativa integrada a suítes de produtividade (Copilot).","macete":"Copilot acessa contexto, sim; e revisão humana continua necessária.","erroComum":"Encadear duas afirmações falsas como se uma justificasse a outra.","comoBancaPensa":"Nega duas características corretas em cadeia, dando a falsa impressão de coerência lógica interna."}},"ES-046":{"cognitivo":{"motivo":"Cobrar que a alucinação em IA generativa pode ocorrer independentemente da qualidade do comando do usuário.","mede":"Inteligência Artificial — IA generativa (fenômeno da alucinação).","pegadinhaDesc":"A banca pode restringir a alucinação apenas a comandos mal formulados pelo usuário.","ondeErra":"Acha que a alucinação só ocorre por erro do usuário, ignorando que é uma limitação intrínseca do modelo.","palavraCritica":"mesmo quando o comando ... está correto e bem formulado","tecnica":"A 'alucinação' é a geração, pelo modelo, de informações incorretas, inventadas ou inexistentes, apresentadas com aparência de veracidade — trata-se de uma limitação intrínseca do funcionamento estatístico do modelo, que pode ocorrer mesmo diante de um comando (prompt) claro e corretamente formulado.","regraMental":"Alucinação é limitação do próprio modelo — não depende só do comando do usuário estar certo."},"comentario":{"resolucao":"CERTO. A alucinação consiste na geração de informações incorretas ou inexistentes, apresentadas com aparência de veracidade, sendo uma limitação intrínseca do funcionamento estatístico dos modelos de IA generativa — podendo ocorrer mesmo quando o comando fornecido pelo usuário está correto e bem formulado.","fundamento":"Doutrina de Inteligência Artificial — IA generativa (fenômeno da alucinação).","macete":"Alucinação é falha do modelo, não só do usuário.","erroComum":"Restringir a ocorrência da alucinação apenas a comandos mal formulados.","comoBancaPensa":"Cobra a compreensão de que a alucinação é uma limitação estrutural do modelo, e não apenas erro de operação do usuário."}},"ES-047":{"cognitivo":{"motivo":"Cobrar, na forma invertida, que a alucinação é limitação do modelo, e não apenas erro do usuário.","mede":"Inteligência Artificial — IA generativa (fenômeno da alucinação).","pegadinhaDesc":"A banca restringe a causa da alucinação exclusivamente ao usuário, usando palavras absolutas.","ondeErra":"Acredita que um comando (prompt) bem formulado é garantia suficiente contra a alucinação.","palavraCritica":"exclusivamente ... não se verificando em hipótese alguma","tecnica":"A alucinação é uma limitação intrínseca do funcionamento estatístico dos modelos de IA generativa, podendo ocorrer independentemente da qualidade do comando fornecido — inclusive diante de prompts corretos e bem formulados.","regraMental":"Alucinação pode ocorrer mesmo com prompt perfeito — é falha do modelo, não só do usuário."},"comentario":{"resolucao":"ERRADO. A alucinação é uma limitação intrínseca dos modelos de IA generativa e pode ocorrer independentemente da qualidade do comando fornecido pelo usuário, inclusive diante de prompts corretos e bem formulados — não se trata de fenômeno exclusivo de comandos incorretos.","fundamento":"Doutrina de Inteligência Artificial — IA generativa (fenômeno da alucinação).","macete":"Prompt perfeito não garante ausência de alucinação.","erroComum":"Atribuir a alucinação exclusivamente a falhas do usuário na formulação do comando.","comoBancaPensa":"Usa palavras absolutas ('exclusivamente', 'em hipótese alguma') para restringir indevidamente a causa do fenômeno."}},"ES-048":{"cognitivo":{"motivo":"Cobrar a definição correta e completa do aprendizado de máquina.","mede":"Inteligência Artificial — fundamentos do Machine Learning.","pegadinhaDesc":"A banca pode negar a dependência de dados de qualidade para a generalização do modelo.","ondeErra":"Ignora que a qualidade e a quantidade dos dados de treinamento afetam diretamente a capacidade de generalização do modelo.","palavraCritica":"quantidade e qualidade dos dados fornecidos","tecnica":"O aprendizado de máquina permite que sistemas aprendam padrões e tomem decisões a partir de dados, sem programação explícita para cada tarefa. Quanto mais dados relevantes e de qualidade forem fornecidos no treinamento, melhor tende a ser a capacidade de generalização do modelo.","regraMental":"ML: aprende sem programação explícita por tarefa + depende de dados de qualidade para generalizar bem."},"comentario":{"resolucao":"CERTO. O aprendizado de máquina é subcampo da IA que permite que sistemas aprendam padrões e tomem decisões sem programação explícita para cada tarefa, sendo sua capacidade de generalização diretamente dependente da quantidade e da qualidade dos dados utilizados no treinamento.","fundamento":"Doutrina de Inteligência Artificial — fundamentos do Machine Learning.","macete":"Mais dados relevantes e de qualidade → melhor generalização do modelo.","erroComum":"Ignorar a relação entre qualidade dos dados de treinamento e capacidade de generalização.","comoBancaPensa":"Item 'limpo' e tecnicamente correto sobre os fundamentos do aprendizado de máquina."}},"ES-049":{"cognitivo":{"motivo":"Cobrar, na forma invertida, que o Machine Learning é software/técnica, e não hardware, e que não elimina erros.","mede":"Inteligência Artificial — fundamentos do Machine Learning.","pegadinhaDesc":"A banca classifica o ML como hardware e afirma que ele elimina totalmente erros de previsão.","ondeErra":"Confunde o conceito computacional (algoritmo/técnica) com um componente físico de hardware.","palavraCritica":"tipo de hardware ... eliminar totalmente","tecnica":"O Machine Learning é um campo de algoritmos e técnicas computacionais (não um componente de hardware), e nenhum modelo de aprendizado de máquina elimina totalmente os erros de previsão — sempre existe alguma margem de erro, medida por métricas de desempenho.","regraMental":"ML é técnica/algoritmo, não hardware. Nenhum modelo elimina erros por completo."},"comentario":{"resolucao":"ERRADO. O Machine Learning é um campo de algoritmos e técnicas computacionais de aprendizado a partir de dados, e não um tipo de hardware de data center. Além disso, nenhum modelo de aprendizado de máquina elimina totalmente a ocorrência de erros de previsão.","fundamento":"Doutrina de Inteligência Artificial — fundamentos do Machine Learning.","macete":"ML é software/algoritmo, não hardware. Erros de previsão nunca são zerados por completo.","erroComum":"Confundir o conceito de Machine Learning com um componente de infraestrutura física.","comoBancaPensa":"Classifica erroneamente o conceito e, ainda, exagera sua capacidade preditiva."}},"ES-050":{"cognitivo":{"motivo":"Cobrar os três tipos clássicos de aprendizado de máquina e suas características distintivas.","mede":"Inteligência Artificial — tipos de aprendizado de máquina.","pegadinhaDesc":"A banca pode inverter as características de cada tipo ou omitir um deles.","ondeErra":"Confunde as três categorias entre si (rótulos, ausência de rótulos, recompensas/penalidades).","palavraCritica":"supervisionado ... não supervisionado ... por reforço","tecnica":"Aprendizado supervisionado: usa dados rotulados (com respostas corretas conhecidas). Não supervisionado: identifica padrões em dados sem rótulos. Por reforço: aprende por tentativa e erro, recebendo recompensas e penalidades ao interagir com um ambiente.","regraMental":"Supervisionado = rótulo. Não supervisionado = sem rótulo. Reforço = recompensa/punição."},"comentario":{"resolucao":"CERTO. Os três tipos clássicos de aprendizado de máquina são corretamente descritos: supervisionado (dados rotulados), não supervisionado (identificação de padrões sem rótulos) e por reforço (aprendizado por recompensas e penalidades em interações com o ambiente).","fundamento":"Doutrina de Inteligência Artificial — tipos de aprendizado de máquina.","macete":"Supervisionado (rótulo), não supervisionado (sem rótulo), reforço (recompensa/punição).","erroComum":"Inverter as características entre os três tipos de aprendizado.","comoBancaPensa":"Item de fixação clássico sobre a taxonomia central do aprendizado de máquina."}},"ES-051":{"cognitivo":{"motivo":"Cobrar, na forma invertida, que é o supervisionado (e não o não supervisionado) que depende de dados rotulados.","mede":"Inteligência Artificial — tipos de aprendizado de máquina (supervisionado x não supervisionado).","pegadinhaDesc":"A banca inverte completamente a dependência de rótulos entre os dois tipos de aprendizado.","ondeErra":"Troca as características de supervisionado e não supervisionado entre si.","palavraCritica":"supervisionado dispensa ... não supervisionado ... depende de rótulos","tecnica":"É exatamente o oposto: o aprendizado SUPERVISIONADO é que depende de dados rotulados (com respostas corretas conhecidas) para treinar o modelo; o aprendizado NÃO SUPERVISIONADO, por sua vez, dispensa rótulos, identificando padrões e tendências nos dados por conta própria.","regraMental":"Supervisionado precisa de rótulo. Não supervisionado dispensa rótulo."},"comentario":{"resolucao":"ERRADO. As definições foram completamente invertidas: é o aprendizado supervisionado que depende de dados rotulados, e o aprendizado não supervisionado que dispensa rótulos, identificando padrões e tendências nos dados de forma autônoma.","fundamento":"Doutrina de Inteligência Artificial — tipos de aprendizado de máquina (supervisionado x não supervisionado).","macete":"Supervisionado = COM rótulo. Não supervisionado = SEM rótulo.","erroComum":"Inverter a dependência de rótulos entre os dois tipos de aprendizado.","comoBancaPensa":"Troca as características centrais dos dois tipos de aprendizado entre si, invertendo a lógica correta."}},"ES-052":{"cognitivo":{"motivo":"Cobrar a definição correta de embeddings e sua função na busca semântica.","mede":"Inteligência Artificial — representações vetoriais (embeddings).","pegadinhaDesc":"A banca pode trocar 'embeddings' por outro termo técnico (token, prompt, parâmetro, logit).","ondeErra":"Confunde embeddings com outros termos técnicos de IA que têm funções distintas.","palavraCritica":"embeddings","tecnica":"Embeddings são representações vetoriais numéricas densas, de dimensão fixa, geradas a partir de textos (palavras, frases ou documentos), de modo que vetores próximos no espaço numérico correspondam a significados semanticamente próximos — base técnica da busca semântica.","regraMental":"Embeddings = vetores de significado. Vetores próximos = significados parecidos."},"comentario":{"resolucao":"CERTO. Os embeddings são representações numéricas densas, de dimensão fixa, geradas a partir de textos, de modo que a proximidade entre os vetores reflita a similaridade semântica entre os textos originais — mecanismo central da busca semântica em sistemas baseados em modelos de linguagem.","fundamento":"Doutrina de Inteligência Artificial — representações vetoriais (embeddings) e busca semântica.","macete":"Embeddings = texto virou vetor; vetor perto = significado parecido.","erroComum":"Confundir embeddings com tokens (unidades de divisão do texto) ou prompts (comandos de entrada).","comoBancaPensa":"Item de fixação técnica sobre um conceito central de busca semântica em IA."}},"ES-053":{"cognitivo":{"motivo":"Cobrar, na forma invertida, que a representação vetorial de similaridade semântica é embedding, não token.","mede":"Inteligência Artificial — representações vetoriais (embeddings x tokens).","pegadinhaDesc":"A banca atribui à token a função de embedding, confundindo dois conceitos distintos.","ondeErra":"Confunde token (unidade de divisão textual) com embedding (representação vetorial de significado).","palavraCritica":"denominada token","tecnica":"Token é a unidade em que o texto é dividido para processamento (palavras, subpalavras ou caracteres), mas não é a representação vetorial usada para medir similaridade semântica — essa função é exercida pelos embeddings, vetores numéricos densos derivados, inclusive, do processamento dos tokens.","regraMental":"Token = pedaço do texto. Embedding = vetor de significado. Não são a mesma coisa."},"comentario":{"resolucao":"ERRADO. A representação vetorial que reflete a similaridade semântica entre textos, usada em busca semântica, é denominada embedding, e não token. O token é apenas a unidade de divisão do texto para processamento, servindo de insumo para a geração dos embeddings, mas não se confunde com eles.","fundamento":"Doutrina de Inteligência Artificial — representações vetoriais (embeddings x tokens).","macete":"Busca semântica usa embeddings, não tokens.","erroComum":"Confundir token (unidade textual) com embedding (vetor de significado).","comoBancaPensa":"Troca o termo técnico correto por outro relacionado, mas com função distinta."}},"ES-054":{"cognitivo":{"motivo":"Cobrar a definição correta de Deep Learning como subconjunto do Machine Learning baseado em redes profundas.","mede":"Inteligência Artificial — Deep Learning.","pegadinhaDesc":"A banca pode negar a relação de subconjunto entre Deep Learning e Machine Learning.","ondeErra":"Trata o Deep Learning como um campo totalmente independente do Machine Learning.","palavraCritica":"subconjunto do aprendizado de máquina","tecnica":"O Deep Learning é um subconjunto (uma especialização) do Machine Learning que utiliza redes neurais artificiais com múltiplas camadas (redes profundas), nas quais pesos e vieses distintos são ajustados em cada camada e neurônio durante o treinamento.","regraMental":"Deep Learning ⊂ Machine Learning ⊂ Inteligência Artificial — sempre com redes multicamadas."},"comentario":{"resolucao":"CERTO. O Deep Learning é, de fato, um subconjunto do aprendizado de máquina, caracterizado pelo uso de redes neurais artificiais com múltiplas camadas, nas quais pesos e vieses distintos são atribuídos a cada camada e a cada neurônio artificial ao longo do treinamento.","fundamento":"Doutrina de Inteligência Artificial — Deep Learning (aprendizado profundo).","macete":"Deep Learning = ML + redes neurais com muitas camadas.","erroComum":"Tratar o Deep Learning como um campo independente do Machine Learning.","comoBancaPensa":"Item 'limpo' sobre a relação de subconjunto e a estrutura técnica do Deep Learning."}},"ES-055":{"cognitivo":{"motivo":"Cobrar, na forma invertida, que o Deep Learning é compatível com os três tipos de aprendizado (supervisionado, não supervisionado e por reforço).","mede":"Inteligência Artificial — Deep Learning e tipos de aprendizado.","pegadinhaDesc":"A banca restringe indevidamente o Deep Learning a apenas um tipo de aprendizado.","ondeErra":"Acha que 'redes profundas' implica necessariamente 'aprendizado não supervisionado', confundindo arquitetura com paradigma de treinamento.","palavraCritica":"trabalha sempre ... não sendo compatível","tecnica":"O Deep Learning é uma arquitetura (redes neurais multicamadas) que pode ser aplicada em qualquer um dos três paradigmas de aprendizado: supervisionado (ex.: classificação de imagens rotuladas), não supervisionado (ex.: agrupamento) e por reforço (ex.: jogos e robótica) — não há exclusividade com o não supervisionado.","regraMental":"Deep Learning é arquitetura; funciona com supervisionado, não supervisionado E por reforço."},"comentario":{"resolucao":"ERRADO. O Deep Learning não trabalha exclusivamente com aprendizado não supervisionado — sua arquitetura de redes neurais multicamadas é compatível com os três paradigmas de aprendizado: supervisionado, não supervisionado e por reforço, dependendo da aplicação.","fundamento":"Doutrina de Inteligência Artificial — Deep Learning e paradigmas de aprendizado.","macete":"Deep Learning é arquitetura — funciona com qualquer um dos três tipos de aprendizado.","erroComum":"Confundir a arquitetura de redes profundas com um único paradigma de aprendizado.","comoBancaPensa":"Usa a palavra absoluta 'sempre' para restringir indevidamente a compatibilidade do Deep Learning."}},"ES-056":{"cognitivo":{"motivo":"Cobrar a definição correta do aprendizado não supervisionado.","mede":"Inteligência Artificial — aprendizado não supervisionado.","pegadinhaDesc":"A banca pode atribuir a esse tipo de aprendizado a necessidade de dados rotulados.","ondeErra":"Confunde aprendizado não supervisionado com supervisionado quanto à necessidade de rótulos.","palavraCritica":"inferir suas próprias regras ... sem respostas corretas rotuladas","tecnica":"No aprendizado não supervisionado, o modelo precisa inferir suas próprias regras a partir de dados sem rótulos (sem respostas corretas conhecidas), com o objetivo de identificar padrões, agrupamentos ou estruturas relevantes nesses dados.","regraMental":"Não supervisionado: sem rótulo, o modelo 'se vira sozinho' para achar padrões."},"comentario":{"resolucao":"CERTO. O aprendizado não supervisionado é definido justamente pela ausência de rótulos nos dados de treinamento, exigindo que o próprio modelo infira regras e identifique padrões significativos de forma autônoma.","fundamento":"Doutrina de Inteligência Artificial — aprendizado não supervisionado.","macete":"Sem rótulo + acha padrão sozinho = aprendizado não supervisionado.","erroComum":"Confundir com o aprendizado supervisionado, que depende de dados rotulados.","comoBancaPensa":"Item de fixação sobre a definição precisa do aprendizado não supervisionado."}},"ES-057":{"cognitivo":{"motivo":"Cobrar, na forma invertida, que o aprendizado não supervisionado dispensa dados rotulados.","mede":"Inteligência Artificial — aprendizado não supervisionado (dependência de rótulos).","pegadinhaDesc":"A banca atribui ao aprendizado não supervisionado uma dependência de rótulos que é, na verdade, do supervisionado.","ondeErra":"Inverte a característica central que diferencia os dois tipos de aprendizado.","palavraCritica":"necessitam de dados rotulados","tecnica":"É exatamente o oposto: os modelos de aprendizado NÃO supervisionado dispensam dados rotulados, identificando padrões e tendências de forma autônoma — a necessidade de rótulos é característica do aprendizado SUPERVISIONADO.","regraMental":"Não supervisionado dispensa rótulo — quem precisa de rótulo é o supervisionado."},"comentario":{"resolucao":"ERRADO. Os modelos de aprendizado não supervisionado dispensam dados rotulados, identificando padrões e tendências nos dados de forma autônoma — a necessidade de dados rotulados é justamente a característica que define o aprendizado supervisionado, e não o não supervisionado.","fundamento":"Doutrina de Inteligência Artificial — aprendizado não supervisionado x supervisionado.","macete":"Rótulo é do supervisionado. Não supervisionado dispensa rótulo.","erroComum":"Inverter a característica central que diferencia os dois tipos de aprendizado.","comoBancaPensa":"Atribui ao aprendizado não supervisionado a característica definidora do aprendizado supervisionado."}},"ES-058":{"cognitivo":{"motivo":"Cobrar a inspiração biológica das redes neurais e a aplicabilidade do aprendizado por reforço em ambientes dinâmicos.","mede":"Inteligência Artificial — redes neurais artificiais e aprendizado por reforço.","pegadinhaDesc":"A banca pode restringir o aprendizado por reforço apenas a dados estáticos.","ondeErra":"Acha que o aprendizado por reforço só se aplica a análises estáticas, sem interação com o ambiente.","palavraCritica":"interação dinâmica com o ambiente","tecnica":"As redes neurais artificiais são inspiradas na estrutura do cérebro humano, ajustando pesos internos ao longo do treinamento para reconhecer padrões complexos. O aprendizado por reforço, por sua vez, é especialmente aplicado em cenários de interação dinâmica com o ambiente (jogos, robótica, sistemas de recomendação em tempo real).","regraMental":"Redes neurais: inspiração no cérebro. Aprendizado por reforço: interação dinâmica com o ambiente."},"comentario":{"resolucao":"CERTO. As redes neurais artificiais são inspiradas no funcionamento do cérebro humano, ajustando pesos para reconhecer padrões complexos a partir de grandes volumes de dados. O aprendizado por reforço, por sua vez, é aplicado justamente em sistemas que envolvem interação dinâmica com o ambiente, como jogos e robótica.","fundamento":"Doutrina de Inteligência Artificial — redes neurais artificiais e aprendizado por reforço.","macete":"Redes neurais = inspiração cerebral. Reforço = interação dinâmica com o ambiente.","erroComum":"Restringir o aprendizado por reforço a análises estáticas de dados.","comoBancaPensa":"Item 'limpo' que combina duas afirmações corretas sobre conceitos distintos de IA."}},"ES-059":{"cognitivo":{"motivo":"Cobrar que sistemas baseados em regras (IA simbólica) também são reconhecidos como inteligência artificial, mesmo sem aprendizado a partir de dados.","mede":"Inteligência Artificial — IA simbólica (sistemas baseados em regras) x aprendizado de máquina.","pegadinhaDesc":"A banca cria um requisito inexistente, exigindo capacidade de aprendizado para que um sistema seja considerado IA.","ondeErra":"Restringe o conceito de inteligência artificial apenas aos sistemas baseados em aprendizado de máquina, ignorando a IA simbólica clássica.","palavraCritica":"requisito indispensável","tecnica":"Sistemas especialistas e outras abordagens de IA simbólica (baseadas em regras lógicas predefinidas, sem aprendizado a partir de dados) são reconhecidos, historicamente, como uma vertente legítima da Inteligência Artificial — o aprendizado de máquina é apenas uma das abordagens possíveis dentro do campo mais amplo da IA, não um requisito para toda e qualquer definição de sistema inteligente.","regraMental":"IA não exige aprendizado de máquina — sistemas de regras (IA simbólica) também são IA."},"comentario":{"resolucao":"ERRADO. Sistemas baseados exclusivamente em regras lógicas predefinidas (IA simbólica, como sistemas especialistas) são reconhecidos como uma vertente legítima da Inteligência Artificial, ainda que não possuam capacidade de aprendizado a partir de dados — o aprendizado de máquina é apenas uma das abordagens dentro do campo mais amplo da IA, e não um requisito indispensável para toda e qualquer definição de sistema inteligente.","fundamento":"Doutrina de Inteligência Artificial — IA simbólica (sistemas baseados em regras) x aprendizado de máquina.","macete":"IA é mais ampla que ML — sistemas de regras (IA simbólica) também contam como IA.","erroComum":"Restringir o conceito de IA apenas aos sistemas que aprendem a partir de dados.","comoBancaPensa":"Cria um requisito conceitual inexistente para excluir uma vertente legítima e histórica da IA."}},"ES-060":{"cognitivo":{"motivo":"Cobrar a distinção conceitual básica entre estatística (medida da amostra) e parâmetro (medida da população).","mede":"Estatística — Análise Exploratória de Dados (amostragem, conceitos fundamentais).","pegadinhaDesc":"A banca pode inverter os termos, atribuindo 'estatística' à população e 'parâmetro' à amostra.","ondeErra":"Troca as definições de estatística e parâmetro, invertendo qual se refere à amostra e qual se refere à população.","palavraCritica":"estatística ... amostra ... parâmetro ... população","tecnica":"Em estatística, uma ESTATÍSTICA é uma medida numérica calculada a partir dos dados de uma AMOSTRA (por exemplo, a média amostral). Um PARÂMETRO é uma medida numérica que descreve uma característica da POPULAÇÃO inteira (por exemplo, a média populacional). A inferência estatística usa estatísticas amostrais para estimar parâmetros populacionais.","regraMental":"EstatíSTICA → amoSTra. PArâmetro → POpulação. (mnemônico pelas sílabas em comum)"},"comentario":{"resolucao":"CERTO. Uma estatística é uma medida numérica calculada a partir dos dados de uma amostra (ex.: média amostral, desvio padrão amostral), ao passo que um parâmetro é uma medida numérica que descreve uma característica da população como um todo (ex.: média populacional).","fundamento":"Doutrina de Estatística — conceitos fundamentais de amostragem e inferência estatística.","macete":"Estatística = amostra. Parâmetro = população. Nunca inverter.","erroComum":"Trocar as definições, atribuindo 'estatística' à população e 'parâmetro' à amostra.","comoBancaPensa":"Item 'limpo' que testa a distinção mais básica e mais cobrada da inferência estatística."}},"ES-061":{"cognitivo":{"motivo":"Cobrar, na forma invertida, que é a estatística (e não o parâmetro) que se refere à amostra, e o parâmetro (e não a estatística) que se refere à população.","mede":"Estatística — Análise Exploratória de Dados (amostragem, conceitos fundamentais).","pegadinhaDesc":"A banca inverte completamente as definições de estatística e parâmetro.","ondeErra":"Aceita a troca de papéis entre os dois conceitos sem perceber a inversão.","palavraCritica":"parâmetro ... amostra ... estatística ... população","tecnica":"É a ESTATÍSTICA que se refere à amostra (medida calculada a partir dos dados amostrais), e o PARÂMETRO que se refere à população (medida que descreve a população como um todo) — o item inverte exatamente essa correspondência.","regraMental":"Sempre que a definição de 'estatística' aparecer ligada à população (ou vice-versa), é erro."},"comentario":{"resolucao":"ERRADO. É a estatística que é medida numérica calculada a partir dos dados de uma amostra, e o parâmetro que descreve uma característica da população como um todo — o item inverte exatamente essas definições.","fundamento":"Doutrina de Estatística — conceitos fundamentais de amostragem e inferência estatística.","macete":"Estatística = amostra. Parâmetro = população. O item trocou os dois.","erroComum":"Aceitar a inversão entre as definições de estatística e parâmetro sem perceber a troca.","comoBancaPensa":"Inverte deliberadamente os dois conceitos centrais da inferência estatística para testar a memorização exata."}},"ES-062":{"cognitivo":{"motivo":"Cobrar que variáveis quantitativas contínuas admitem valores fracionários, obtidas por mensuração.","mede":"Estatística — Análise Exploratória de Dados (tipos de variáveis).","pegadinhaDesc":"A banca pode restringir as variáveis contínuas a valores inteiros, confundindo-as com as discretas.","ondeErra":"Confunde variável quantitativa contínua (mensuração, admite fração) com discreta (contagem, só valores inteiros).","palavraCritica":"qualquer valor numérico ... não corresponda a um número inteiro","tecnica":"Variáveis quantitativas contínuas são obtidas por mensuração e podem assumir qualquer valor numérico dentro de um intervalo, incluindo valores fracionários (ex.: altura = 1,75m, peso = 68,3kg) — diferentemente das variáveis quantitativas discretas, obtidas por contagem, que assumem apenas valores inteiros (ex.: número de filhos).","regraMental":"Contínua = mensuração, admite fração (altura, peso). Discreta = contagem, só inteiros (nº de filhos)."},"comentario":{"resolucao":"CERTO. Variáveis quantitativas contínuas, obtidas por mensuração, podem assumir qualquer valor numérico dentro de um intervalo, inclusive valores fracionários — como ocorre com a altura ou o peso de uma pessoa —, ao contrário das variáveis discretas, que só assumem valores inteiros.","fundamento":"Doutrina de Estatística — classificação de variáveis (quantitativas contínuas x discretas).","macete":"Contínua = mensuração, pode ter fração. Discreta = contagem, só inteiro.","erroComum":"Achar que variáveis quantitativas contínuas só podem assumir valores inteiros.","comoBancaPensa":"Item 'limpo' que reforça a característica central que distingue variáveis contínuas de discretas."}},"ES-063":{"cognitivo":{"motivo":"Cobrar, na forma invertida, que variáveis contínuas admitem valores fracionários, e que essa admissão não as torna discretas.","mede":"Estatística — Análise Exploratória de Dados (tipos de variáveis).","pegadinhaDesc":"A banca inverte as características de contínua e discreta, restringindo a contínua a valores inteiros.","ondeErra":"Troca as definições: atribui à variável contínua a restrição (só inteiros) que, na verdade, é da discreta.","palavraCritica":"somente ... valores numéricos inteiros ... vedada","tecnica":"Variáveis quantitativas contínuas admitem, sim, valores fracionários — é justamente essa a característica que as distingue das discretas (obtidas por contagem, restritas a valores inteiros). Restringir a variável contínua a valores inteiros inverte a classificação correta.","regraMental":"Contínua admite fração; quem é restrita a inteiros é a discreta — nunca o contrário."},"comentario":{"resolucao":"ERRADO. Variáveis quantitativas contínuas admitem valores fracionários (obtidas por mensuração, como altura e peso) — é a variável quantitativa discreta (obtida por contagem) que é restrita a valores inteiros. O item inverte essa classificação.","fundamento":"Doutrina de Estatística — classificação de variáveis (quantitativas contínuas x discretas).","macete":"Restrição a valores inteiros é da discreta, não da contínua — nunca inverter.","erroComum":"Atribuir à variável contínua a restrição a valores inteiros, que pertence à variável discreta.","comoBancaPensa":"Inverte as características centrais de contínua e discreta para testar a memorização exata da distinção."}},"ES-064":{"cognitivo":{"motivo":"Cobrar que uma variável qualitativa com k categorias exige k-1 variáveis dummy para codificação completa, sem redundância.","mede":"Estatística — Análise Exploratória de Dados (variáveis dummy/binárias).","pegadinhaDesc":"A banca pode afirmar que uma única variável dummy é suficiente para representar qualquer variável qualitativa, independentemente do número de categorias.","ondeErra":"Não sabe que uma dummy (binária, 0/1) só distingue 2 categorias — para 3 ou mais, são necessárias múltiplas dummies.","palavraCritica":"não pode ser representada ... duas variáveis dummy","tecnica":"Uma variável dummy é binária (assume apenas os valores 0 ou 1), representando a presença ou ausência de uma categoria. Para codificar uma variável qualitativa com k categorias sem redundância, são necessárias k-1 variáveis dummy — no caso de 3 categorias, são necessárias 2 dummies (a k-ésima categoria fica implícita quando todas as demais dummies são 0).","regraMental":"k categorias → k-1 dummies. 3 categorias → 2 dummies, nunca apenas 1."},"comentario":{"resolucao":"CERTO. Uma variável qualitativa com três categorias não pode ser representada por uma única variável dummy (binária, que só distingue 2 valores) — são necessárias, no mínimo, duas variáveis dummy para codificar as três categorias sem redundância (regra geral: k categorias exigem k-1 dummies).","fundamento":"Doutrina de Estatística — codificação de variáveis qualitativas (variáveis dummy).","macete":"k categorias → k-1 dummies. Nunca apenas uma dummy para 3 ou mais categorias.","erroComum":"Achar que uma única variável dummy é suficiente para representar qualquer variável qualitativa, independentemente do número de categorias.","comoBancaPensa":"Item 'limpo' que exige conhecer a regra de codificação k-1 para variáveis dummy."}},"ES-065":{"cognitivo":{"motivo":"Cobrar, na forma invertida, que uma única variável dummy (binária) só distingue 2 categorias, não sendo suficiente para 3 ou mais.","mede":"Estatística — Análise Exploratória de Dados (variáveis dummy/binárias).","pegadinhaDesc":"A banca generaliza a capacidade da variável dummy, afirmando que ela codifica qualquer número de categorias sozinha.","ondeErra":"Ignora que a variável dummy é binária por definição (0 ou 1), incapaz de codificar mais de 2 categorias isoladamente.","palavraCritica":"qualquer número de categorias em um único indicador binário","tecnica":"A variável dummy é binária, assumindo apenas os valores 0 ou 1 — sozinha, distingue no máximo 2 categorias. Para representar uma variável qualitativa com 3 categorias sem redundância, são necessárias 2 variáveis dummy, e não apenas uma.","regraMental":"Uma dummy sozinha = só 2 categorias. Para 3 ou mais, sempre múltiplas dummies (k-1)."},"comentario":{"resolucao":"ERRADO. A variável dummy é binária por definição, distinguindo no máximo 2 categorias isoladamente. Uma variável qualitativa com 3 categorias exige, no mínimo, 2 variáveis dummy para codificação completa sem redundância — não pode ser representada por uma única dummy.","fundamento":"Doutrina de Estatística — codificação de variáveis qualitativas (variáveis dummy).","macete":"Uma dummy = só 2 categorias. Nunca 'qualquer número' em um único indicador binário.","erroComum":"Achar que a variável dummy, sozinha, pode codificar qualquer quantidade de categorias.","comoBancaPensa":"Generaliza indevidamente a capacidade de uma única variável dummy, ignorando sua natureza binária."}},"ES-066":{"cognitivo":{"motivo":"Cobrar que a média aritmética exige variável quantitativa (métrica), não sendo aplicável a variáveis qualitativas.","mede":"Estatística — Análise Exploratória de Dados (medidas de tendência central).","pegadinhaDesc":"A banca pode afirmar que a média pode ser calculada também para variáveis qualitativas ordinais ou nominais.","ondeErra":"Confunde a possibilidade de atribuir códigos numéricos a categorias qualitativas com a existência de uma média aritmética significativa.","palavraCritica":"necessariamente do tipo métrica ... não sendo possível","tecnica":"A média aritmética pressupõe operações matemáticas (soma e divisão) que só fazem sentido em variáveis métricas (quantitativas, de escala intervalar ou de razão). Variáveis qualitativas nominais (ex.: cor dos olhos) e ordinais (ex.: escolaridade) não admitem média aritmética significativa, ainda que sejam codificadas numericamente — nesses casos, usam-se moda (nominal) ou mediana (ordinal).","regraMental":"Média exige variável métrica (quantitativa). Nominal usa moda; ordinal usa mediana."},"comentario":{"resolucao":"CERTO. O cálculo da média aritmética exige que a variável seja do tipo métrica (quantitativa) — não é possível calcular uma média aritmética significativa a partir de dados qualitativos nominais ou ordinais, ainda que codificados numericamente. Para esses casos, usam-se moda ou mediana.","fundamento":"Doutrina de Estatística — medidas de tendência central e níveis de mensuração.","macete":"Média = variável métrica. Nominal → moda. Ordinal → mediana.","erroComum":"Achar que a média aritmética pode ser calculada para qualquer variável, inclusive qualitativas codificadas numericamente.","comoBancaPensa":"Item 'limpo' que reforça a exigência de nível de mensuração adequado para cada medida de tendência central."}},"ES-067":{"cognitivo":{"motivo":"Cobrar, na forma invertida, que a mera codificação numérica de categorias qualitativas não torna a média aritmética significativa.","mede":"Estatística — Análise Exploratória de Dados (medidas de tendência central).","pegadinhaDesc":"A banca afirma que a codificação numérica de categorias qualitativas já habilita o cálculo de uma média significativa.","ondeErra":"Confunde a atribuição de códigos numéricos arbitrários a categorias com a existência de uma escala métrica real.","palavraCritica":"qualquer tipo de variável ... bastando ... codificadas","tecnica":"Ainda que categorias qualitativas sejam codificadas com números (ex.: 1 para 'masculino', 2 para 'feminino'), essa codificação é arbitrária e não confere significado matemático à média aritmética resultante. A média exige variável métrica (quantitativa) — para variáveis nominais usa-se a moda, e para ordinais, a mediana.","regraMental":"Codificar número em categoria não vira variável métrica — a média continua sem sentido nesses casos."},"comentario":{"resolucao":"ERRADO. A média aritmética exige variável métrica (quantitativa) para ter significado estatístico — a mera codificação numérica de categorias qualitativas nominais ou ordinais não torna essa média significativa. Para essas variáveis, usam-se moda (nominal) ou mediana (ordinal).","fundamento":"Doutrina de Estatística — medidas de tendência central e níveis de mensuração.","macete":"Codificação numérica arbitrária não cria escala métrica — a média continua sem sentido.","erroComum":"Achar que basta atribuir números às categorias qualitativas para poder calcular uma média significativa.","comoBancaPensa":"Generaliza indevidamente a aplicabilidade da média aritmética para qualquer variável, ignorando a exigência do nível de mensuração."}},"ES-068":{"cognitivo":{"motivo":"Cobrar que variáveis que remetem a uma ideia de ordem (como dias da semana) são qualitativas ordinais, e não quantitativas.","mede":"Estatística — Análise Exploratória de Dados (classificação de variáveis).","pegadinhaDesc":"A banca pode classificar dias da semana (ou variáveis semelhantes) como 'quantitativas ordinais', categoria que sequer existe na classificação padrão.","ondeErra":"Confunde 'ordem entre categorias' com 'natureza quantitativa', criando uma categoria inexistente ('quantitativa ordinal').","palavraCritica":"qualitativa ordinal ... e não de variável quantitativa","tecnica":"A classificação padrão de variáveis divide-se em qualitativas (nominais ou ordinais) e quantitativas (discretas ou contínuas). 'Ordinal' é uma subdivisão exclusiva das variáveis QUALITATIVAS — não existe 'variável quantitativa ordinal'. Dias da semana expressam ordem entre categorias, mas não são somáveis nem divisíveis com sentido numérico, sendo, portanto, qualitativas ordinais.","regraMental":"Ordinal é sempre qualitativa. Não existe 'quantitativa ordinal' na classificação padrão."},"comentario":{"resolucao":"CERTO. Os dias da semana são exemplo de variável qualitativa ordinal, e não quantitativa — expressam uma ordem entre categorias, mas essa ordem não corresponde a uma medida numérica passível de operações aritméticas (não faz sentido somar ou dividir 'terça-feira').","fundamento":"Doutrina de Estatística — classificação de variáveis (qualitativas nominais/ordinais x quantitativas discretas/contínuas).","macete":"'Ordinal' só existe como subtipo de qualitativa — nunca de quantitativa.","erroComum":"Classificar variáveis com ordem entre categorias (como dias da semana) como 'quantitativas ordinais', categoria inexistente.","comoBancaPensa":"Item 'limpo' que corrige uma confusão comum entre 'ordem entre categorias' e 'natureza quantitativa'."}},"ES-069":{"cognitivo":{"motivo":"Cobrar, na forma invertida, que 'ordinal' é subtipo exclusivo de variável qualitativa, e que dias da semana não são variáveis quantitativas.","mede":"Estatística — Análise Exploratória de Dados (classificação de variáveis).","pegadinhaDesc":"A banca cria a categoria inexistente 'variável quantitativa ordinal', classificando erroneamente dias da semana e horas do dia como quantitativos.","ondeErra":"Acredita que a existência de uma ordem entre categorias (dias da semana) já basta para classificar a variável como quantitativa.","palavraCritica":"variáveis quantitativas podem ser do tipo ordinais","tecnica":"'Ordinal' é subdivisão exclusiva das variáveis QUALITATIVAS, e não das quantitativas. As variáveis quantitativas se dividem em discretas e contínuas — nunca em 'ordinais'. Dias da semana e horas do dia (quando tratadas como categorias cíclicas de ordem) são exemplos de variáveis qualitativas ordinais, não quantitativas.","regraMental":"Quantitativa = discreta ou contínua. Ordinal é sempre qualitativa — nunca aparece como subtipo de quantitativa."},"comentario":{"resolucao":"ERRADO. 'Ordinal' é subdivisão exclusiva das variáveis qualitativas, e não das quantitativas — estas se dividem em discretas e contínuas. Dias da semana e horas do dia, quando tratados como categorias que expressam ordem, são exemplos de variáveis qualitativas ordinais, e não quantitativas.","fundamento":"Doutrina de Estatística — classificação de variáveis (qualitativas nominais/ordinais x quantitativas discretas/contínuas).","macete":"Nunca existe 'variável quantitativa ordinal' — ordinal é sempre qualitativa.","erroComum":"Classificar como quantitativas variáveis que apenas expressam ordem entre categorias, sem natureza numérica somável.","comoBancaPensa":"Cria uma categoria de classificação inexistente para testar se o candidato decorou a árvore de classificação sem entendê-la."}},"ES-070":{"cognitivo":{"motivo":"Cobrar que a escolha de cores em visualizações de dados tem impacto significativo na interpretação, e não é um detalhe irrelevante.","mede":"Estatística — Análise Exploratória de Dados (visualização de dados, boas práticas).","pegadinhaDesc":"A banca pode minimizar a importância das cores, afirmando que elas têm pouca ou nenhuma influência na leitura dos dados.","ondeErra":"Trata a escolha de cores como um aspecto puramente estético, sem relevância analítica.","palavraCritica":"influência relevante ... distorcer","tecnica":"Em visualização de dados (data visualization), a escolha de cores é elemento central de boas práticas: cores mal escolhidas podem confundir categorias, sugerir hierarquias inexistentes, dificultar a leitura por pessoas com daltonismo ou até induzir conclusões equivocadas sobre os dados representados.","regraMental":"Cor em gráfico não é estética pura — é ferramenta analítica que pode ajudar ou atrapalhar a leitura dos dados."},"comentario":{"resolucao":"CERTO. A escolha das cores em um gráfico tem influência relevante na interpretação dos dados, podendo destacar, ofuscar ou distorcer a percepção de padrões, tendências e comparações entre categorias — é elemento central das boas práticas de visualização de dados.","fundamento":"Doutrina de Estatística e Ciência de Dados — visualização de dados (data visualization).","macete":"Cor em gráfico é ferramenta analítica, não só estética — influencia diretamente a leitura dos dados.","erroComum":"Tratar a escolha de cores como um detalhe estético irrelevante para a interpretação dos dados.","comoBancaPensa":"Item 'limpo' que reforça a relevância prática de um tema frequentemente subestimado em provas de estatística aplicada."}},"ES-071":{"cognitivo":{"motivo":"Cobrar, na forma invertida, que a escolha de cores tem influência relevante (e não pouca ou nula) na interpretação de dados visualizados.","mede":"Estatística — Análise Exploratória de Dados (visualização de dados, boas práticas).","pegadinhaDesc":"A banca minimiza a importância das cores, tratando-as como um detalhe puramente decorativo.","ondeErra":"Acredita que a escolha de cores em gráficos é irrelevante para a correta interpretação dos dados.","palavraCritica":"pouca influência ... meramente estético","tecnica":"A escolha de cores é elemento central das boas práticas de visualização de dados, podendo influenciar significativamente a interpretação — destacando, ofuscando ou até distorcendo a percepção de padrões e comparações entre categorias. Não se trata de aspecto meramente estético.","regraMental":"Cor em gráfico nunca é 'pouca influência' — é elemento central da análise visual dos dados."},"comentario":{"resolucao":"ERRADO. A escolha das cores em um gráfico tem influência relevante — e não pouca ou nula — na interpretação dos dados, podendo destacar, ofuscar ou distorcer a percepção de padrões e comparações entre categorias. Não se trata de aspecto meramente estético.","fundamento":"Doutrina de Estatística e Ciência de Dados — visualização de dados (data visualization).","macete":"Nunca é 'pouca influência' — cor é ferramenta analítica central na visualização de dados.","erroComum":"Subestimar a importância da escolha de cores, tratando-a como puramente decorativa.","comoBancaPensa":"Minimiza a relevância de um elemento técnico central da visualização de dados, testando o conhecimento prático do tema."}},"ES-072":{"cognitivo":{"motivo":"Cobrar que o gráfico de pizza é adequado para poucas categorias, e não para grandes conjuntos de dados complexos.","mede":"Estatística — Análise Exploratória de Dados (visualização de dados, gráfico de setores).","pegadinhaDesc":"A banca pode afirmar que o gráfico de pizza é a melhor escolha justamente para grandes conjuntos de dados complexos.","ondeErra":"Acha que o gráfico de pizza funciona bem com muitas categorias ou dados complexos, quando na verdade se torna ilegível nesses casos.","palavraCritica":"não é a melhor escolha ... poucas categorias","tecnica":"O gráfico de setores (pizza) é adequado para representar a distribuição proporcional de uma variável qualitativa com POUCAS categorias, permitindo comparação visual das fatias. Com muitas categorias ou dados complexos, o gráfico se torna poluído e de difícil leitura, sendo preferíveis gráficos de barras ou outras visualizações.","regraMental":"Pizza: boa para poucas categorias. Muitas categorias/dados complexos: pizza vira poluição visual, prefira barras."},"comentario":{"resolucao":"CERTO. O gráfico de setores (pizza) não é a melhor escolha para grandes conjuntos de dados complexos — é mais adequado para representar a distribuição proporcional de uma variável qualitativa com poucas categorias, sob pena de se tornar visualmente poluído e de difícil leitura com muitas fatias.","fundamento":"Doutrina de Estatística e Ciência de Dados — visualização de dados (limitações do gráfico de setores).","macete":"Pizza: poucas categorias, sim. Muitas categorias/dados complexos: prefira gráfico de barras.","erroComum":"Achar que o gráfico de pizza é adequado para representar grandes volumes de dados ou muitas categorias.","comoBancaPensa":"Item 'limpo' que reforça uma limitação prática bem estabelecida na literatura de visualização de dados."}},"ES-073":{"cognitivo":{"motivo":"Cobrar, na forma invertida, que o gráfico de pizza se torna ilegível com muitas categorias, não sendo adequado para dados complexos.","mede":"Estatística — Análise Exploratória de Dados (visualização de dados, gráfico de setores).","pegadinhaDesc":"A banca inverte completamente a limitação conhecida do gráfico de pizza, apresentando-o como ideal para grandes volumes de dados.","ondeErra":"Acredita que o gráfico de pizza mantém a clareza de leitura mesmo com um número elevado de categorias.","palavraCritica":"melhor escolha ... elevado número de categorias ... sem prejuízo","tecnica":"O gráfico de setores (pizza) é adequado apenas para poucas categorias — com um número elevado delas, as fatias se tornam pequenas e de difícil distinção visual, prejudicando a leitura. Para grandes conjuntos de dados complexos, gráficos de barras ou outras visualizações são preferíveis.","regraMental":"Pizza com muitas fatias = ilegível. Nunca é a 'melhor escolha' para dados complexos ou muitas categorias."},"comentario":{"resolucao":"ERRADO. O gráfico de pizza não é a melhor escolha para grandes conjuntos de dados complexos — com um número elevado de categorias, as fatias tornam-se pequenas e de difícil distinção visual, prejudicando a clareza da leitura. Nesses casos, são preferíveis gráficos de barras ou outras visualizações.","fundamento":"Doutrina de Estatística e Ciência de Dados — visualização de dados (limitações do gráfico de setores).","macete":"Pizza nunca é ideal para 'grandes conjuntos complexos' — a legibilidade cai com muitas fatias.","erroComum":"Achar que o gráfico de pizza mantém boa legibilidade independentemente do número de categorias representadas.","comoBancaPensa":"Inverte a limitação conhecida do gráfico de pizza, apresentando-a como uma vantagem, para testar o conhecimento prático de visualização de dados."}},"ES-074":{"cognitivo":{"motivo":"Cobrar que a tabela de frequências, ao agregar dados em contagens por categoria, perde a informação sobre a ordem/sequência original das observações individuais.","mede":"Estatística — Análise Exploratória de Dados (tabelas de distribuição de frequências).","pegadinhaDesc":"A banca pode afirmar que é possível reconstruir a série de dados original a partir da tabela de frequências.","ondeErra":"Acha que uma tabela de frequências preserva informação suficiente para recuperar a ordem exata dos dados coletados.","palavraCritica":"não é possível recuperar a sequência original ... sem preservar a ordem","tecnica":"A tabela de frequências absolutas resume os dados informando apenas quantas vezes cada categoria (ou valor) ocorreu — trata-se de uma medida de resumo (data reduction). A sequência exata em que os dados foram coletados (por exemplo, a ordem cronológica das observações) não é preservada nesse tipo de tabela, sendo uma informação irremediavelmente perdida no processo de agregação.","regraMental":"Tabela de frequências resume contagens, mas apaga a ordem/sequência original dos dados — informação perdida, não recuperável."},"comentario":{"resolucao":"CERTO. A tabela de frequências absolutas informa apenas a contagem de ocorrências por categoria, sem preservar a ordem em que os dados foram originalmente coletados — não é possível, a partir dela, recuperar a sequência original dos valores individuais da série de dados.","fundamento":"Doutrina de Estatística — distribuições de frequência (agregação e perda de informação sequencial).","macete":"Tabela de frequências = contagem por categoria. A ordem original dos dados nunca é recuperável a partir dela.","erroComum":"Achar que a tabela de frequências preserva informação suficiente para reconstruir a sequência exata dos dados coletados.","comoBancaPensa":"Item 'limpo' que reforça um conceito central sobre agregação de dados: resumir é sempre perder alguma informação."}},"ES-075":{"cognitivo":{"motivo":"Cobrar, na forma invertida, que a tabela de frequências não preserva a ordem/sequência original das observações.","mede":"Estatística — Análise Exploratória de Dados (tabelas de distribuição de frequências).","pegadinhaDesc":"A banca afirma que a tabela de frequências permite reconstruir integralmente a série original, incluindo a ordem de coleta.","ondeErra":"Não percebe que a tabela de frequências é uma medida de resumo (agregação), que descarta a informação sobre a ordem original dos dados.","palavraCritica":"é possível recuperar ... incluída a ordem exata","tecnica":"A tabela de frequências absolutas apenas contabiliza quantas vezes cada categoria ocorreu, sem preservar a ordem cronológica ou sequencial das observações originais. Essa informação é perdida no processo de agregação e não pode ser recuperada a partir da tabela resumida.","regraMental":"Tabela de frequências nunca preserva a ordem original — essa informação está irremediavelmente perdida."},"comentario":{"resolucao":"ERRADO. A tabela de frequências absolutas não preserva a ordem em que os dados foram coletados — apenas informa a contagem de ocorrências por categoria. Não é possível, a partir dela, recuperar a sequência original dos valores individuais da série de dados.","fundamento":"Doutrina de Estatística — distribuições de frequência (agregação e perda de informação sequencial).","macete":"Tabela de frequências: contagem sim, ordem original nunca.","erroComum":"Achar que uma tabela resumida de frequências preserva informação suficiente para reconstruir a sequência exata da coleta original.","comoBancaPensa":"Afirma uma capacidade de reconstrução que a agregação estatística, por definição, não permite."}},"ES-076":{"cognitivo":{"motivo":"Cobrar a regra básica de construção do histograma: altura das barras proporcional à frequência.","mede":"Estatística — Análise Exploratória de Dados (histogramas, representação gráfica).","pegadinhaDesc":"A banca pode afirmar que a largura (e não a altura) das barras deve ser proporcional à frequência, ou negar essa proporcionalidade.","ondeErra":"Confunde qual dimensão do histograma (altura x largura) representa a frequência dos dados.","palavraCritica":"altura das barras ... proporcional à frequência","tecnica":"O histograma é a representação gráfica de uma distribuição de frequências de uma variável quantitativa, geralmente contínua, agrupada em classes. A altura de cada barra (retângulo) é proporcional à frequência (absoluta ou relativa) observada na classe correspondente, permitindo visualizar a concentração e a dispersão dos dados.","regraMental":"Histograma: altura da barra = frequência da classe. Quanto mais dados na faixa, mais alta a barra."},"comentario":{"resolucao":"CERTO. Na construção de um histograma, a altura das barras verticais é proporcional à frequência observada de cada valor ou intervalo de classe, permitindo visualizar a distribuição de uma variável quantitativa.","fundamento":"Doutrina de Estatística — representação gráfica de distribuições de frequência (histograma).","macete":"Histograma: altura da barra = frequência da classe.","erroComum":"Confundir a dimensão do histograma (altura) que representa a frequência com a largura das barras.","comoBancaPensa":"Item 'limpo' que reproduz a regra fundamental de construção do histograma."}},"ES-077":{"cognitivo":{"motivo":"Cobrar, na forma invertida, que é a altura (e não a largura) das barras do histograma que representa a frequência de cada classe.","mede":"Estatística — Análise Exploratória de Dados (histogramas, representação gráfica).","pegadinhaDesc":"A banca troca as dimensões do histograma, atribuindo à largura a função de representar a frequência.","ondeErra":"Confunde as duas dimensões visuais do histograma, invertendo qual delas representa a frequência da classe.","palavraCritica":"altura ... sempre igual ... largura ... deve ser ajustado","tecnica":"No histograma, é a ALTURA das barras que é proporcional à frequência (absoluta ou relativa) de cada classe — a largura das barras geralmente corresponde à amplitude do intervalo de classe (que costuma ser constante, salvo em histogramas de classes desiguais). Afirmar que a altura é sempre igual e que a largura representa a frequência inverte essa relação.","regraMental":"Histograma: ALTURA = frequência. Largura normalmente é fixa (amplitude de classe) — nunca o contrário."},"comentario":{"resolucao":"ERRADO. No histograma, é a altura das barras verticais que é proporcional à frequência observada de cada classe — a largura geralmente corresponde à amplitude do intervalo de classe. O item inverte essa relação, atribuindo à largura a função de representar a frequência.","fundamento":"Doutrina de Estatística — representação gráfica de distribuições de frequência (histograma).","macete":"Nunca inverter: altura = frequência. A largura não é o elemento que representa a frequência da classe.","erroComum":"Trocar as dimensões do histograma, atribuindo à largura das barras a representação da frequência de cada classe.","comoBancaPensa":"Inverte a regra fundamental de construção do histograma para testar a memorização exata do conceito."}},"ES-078":{"cognitivo":{"motivo":"Cobrar que aumentar o número de classes (intervalos mais estreitos) reduz a perda de informação, aproximando a representação dos dados originais.","mede":"Estatística — Análise Exploratória de Dados (agrupamento em classes, tabelas de frequência).","pegadinhaDesc":"A banca pode inverter essa relação, afirmando que mais classes geram MAIS perda de informação.","ondeErra":"Confunde a direção da relação entre número de classes e perda de informação, invertendo-a.","palavraCritica":"tanto menor quanto maior for o número de classes","tecnica":"Ao agrupar dados contínuos em classes (intervalos), cada observação passa a ser representada apenas pelo intervalo em que se encaixa, perdendo-se seu valor exato. Quanto MAIS classes (intervalos mais estreitos), MENOR a perda de informação, pois a representação se aproxima mais dos valores individuais reais. Quanto MENOS classes (intervalos mais largos), MAIOR a perda de informação, pois muitos valores distintos são agrupados sob a mesma faixa.","regraMental":"Mais classes (intervalos estreitos) = menos perda de informação. Menos classes (intervalos largos) = mais perda."},"comentario":{"resolucao":"CERTO. Ao agrupar dados contínuos em classes, quanto maior o número de classes escolhidas (intervalos mais estreitos), menor a perda de informação em relação aos dados originais, pois a representação se aproxima mais dos valores individuais reais.","fundamento":"Doutrina de Estatística — distribuições de frequência por classes (agrupamento de dados contínuos).","macete":"Mais classes = intervalos mais estreitos = menos perda de informação.","erroComum":"Inverter a relação, achando que mais classes geram mais perda de informação em vez de menos.","comoBancaPensa":"Item 'limpo' que reforça, na forma correta, a relação entre granularidade das classes e fidelidade aos dados originais."}},"ES-079":{"cognitivo":{"motivo":"Cobrar, na forma invertida, que mais classes (intervalos mais estreitos) reduzem — e não aumentam — a perda de informação.","mede":"Estatística — Análise Exploratória de Dados (agrupamento em classes, tabelas de frequência).","pegadinhaDesc":"A banca inverte a relação real entre número de classes e perda de informação.","ondeErra":"Acredita que aumentar o número de classes (tornando os intervalos mais estreitos) aumenta a perda de informação, quando na verdade a reduz.","palavraCritica":"tanto maior quanto maior for o número de classes","tecnica":"Quanto MAIS classes (intervalos mais estreitos) forem utilizadas para agrupar dados contínuos, MENOR será a perda de informação, pois a representação se aproxima mais dos valores individuais reais. É o oposto — poucas classes (intervalos largos) — que gera MAIOR perda de informação, ao agrupar muitos valores distintos sob a mesma faixa.","regraMental":"Nunca é 'mais classes = mais perda'. É o contrário: mais classes = menos perda de informação."},"comentario":{"resolucao":"ERRADO. A relação está invertida: quanto maior o número de classes (intervalos mais estreitos), MENOR é a perda de informação em relação aos dados originais — e não maior. É o uso de POUCAS classes (intervalos largos) que aumenta a perda de informação.","fundamento":"Doutrina de Estatística — distribuições de frequência por classes (agrupamento de dados contínuos).","macete":"Inverteu a lógica? Desconfie: mais classes sempre aproxima mais dos dados originais, nunca afasta.","erroComum":"Achar que aumentar o número de classes de agrupamento aumenta a perda de informação em relação aos dados originais.","comoBancaPensa":"Inverte deliberadamente uma relação lógica bem estabelecida para testar se o candidato raciocina ou apenas decora padrões."}},"ES-080":{"cognitivo":{"motivo":"Cobrar o cálculo correto da mediana em um conjunto de tamanho par: a média aritmética dos dois valores centrais após a ordenação.","mede":"Estatística — Medidas de Tendência Central (cálculo da mediana).","pegadinhaDesc":"A banca pode apresentar apenas um dos dois valores centrais como sendo a mediana, esquecendo de calcular a média entre eles.","ondeErra":"Toma apenas o 4º ou o 5º valor da série ordenada como mediana, sem calcular a média entre os dois valores centrais.","palavraCritica":"igual a 19 minutos","tecnica":"Com 8 valores já ordenados (12, 15, 15, 18, 20, 22, 25, 30), a mediana de um conjunto de tamanho par é a média aritmética dos dois valores centrais (4º e 5º): (18 + 20) / 2 = 19.","regraMental":"Conjunto par: mediana = média dos dois valores do meio, nunca apenas um deles isoladamente."},"comentario":{"resolucao":"CERTO. Com os dados já ordenados (12, 15, 15, 18, 20, 22, 25, 30), a mediana de um conjunto de 8 valores (par) é a média aritmética dos dois valores centrais, o 4º (18) e o 5º (20): (18 + 20) / 2 = 19 minutos.","fundamento":"Doutrina de Estatística — cálculo da mediana em conjuntos de tamanho par.","macete":"Conjunto par: some os dois valores do meio e divida por 2.","erroComum":"Considerar apenas um dos dois valores centrais (18 ou 20) como sendo a mediana, sem calcular a média entre eles.","comoBancaPensa":"Item 'limpo' que exige o cálculo correto e completo da mediana em conjunto de tamanho par."}},"ES-081":{"cognitivo":{"motivo":"Cobrar, na forma invertida, que a mediana de um conjunto par não é apenas um dos valores centrais isolados, mas a média entre eles.","mede":"Estatística — Medidas de Tendência Central (cálculo da mediana).","pegadinhaDesc":"A banca apresenta apenas o 4º valor da série ordenada (18) como se fosse a mediana completa.","ondeErra":"Esquece de calcular a média entre o 4º e o 5º valores, considerando apenas o primeiro deles como a mediana.","palavraCritica":"igual a 18 minutos","tecnica":"Com os dados ordenados (12, 15, 15, 18, 20, 22, 25, 30), a mediana de um conjunto de 8 valores (par) exige a média aritmética dos dois valores centrais — o 4º (18) e o 5º (20): (18 + 20) / 2 = 19, e não apenas 18.","regraMental":"Nunca tome só um dos dois valores centrais como mediana em conjunto par — é preciso somar e dividir por 2."},"comentario":{"resolucao":"ERRADO. A mediana correta é 19 minutos, e não 18. Com os dados ordenados (12, 15, 15, 18, 20, 22, 25, 30), a mediana de um conjunto de 8 valores é a média aritmética entre o 4º valor (18) e o 5º valor (20): (18 + 20) / 2 = 19.","fundamento":"Doutrina de Estatística — cálculo da mediana em conjuntos de tamanho par.","macete":"18 é só o 4º valor — a mediana real é a média entre o 4º e o 5º, que dá 19.","erroComum":"Parar no primeiro dos dois valores centrais e esquecer de calcular a média com o segundo.","comoBancaPensa":"Apresenta um valor real da série (18), mas que não corresponde à mediana correta, testando o cálculo completo."}},"ES-082":{"cognitivo":{"motivo":"Cobrar o cálculo correto da moda: o valor que ocorre com maior frequência no conjunto de dados.","mede":"Estatística — Medidas de Tendência Central (cálculo da moda).","pegadinhaDesc":"A banca pode atribuir a moda a um valor que aparece apenas uma vez no conjunto.","ondeErra":"Confunde a moda com o valor mínimo, o máximo ou qualquer outro valor que não seja o mais frequente.","palavraCritica":"igual a 25 anos","tecnica":"No conjunto de dados (22, 25, 25, 25, 28, 30, 32, 35, 40), o valor 25 aparece 3 vezes — mais do que qualquer outro valor, que aparece apenas uma vez cada. Portanto, a moda do conjunto é 25.","regraMental":"Moda = valor que mais se repete. Contar a frequência de cada valor é o único caminho seguro."},"comentario":{"resolucao":"CERTO. No conjunto de dados (22, 25, 25, 25, 28, 30, 32, 35, 40), o valor 25 é o único que se repete (aparece 3 vezes), sendo, portanto, a moda do conjunto.","fundamento":"Doutrina de Estatística — cálculo da moda (medida de tendência central).","macete":"Moda = valor mais frequente. Conte as repetições, não olhe só para a posição na lista.","erroComum":"Atribuir a moda a um valor que aparece apenas uma vez no conjunto de dados.","comoBancaPensa":"Item 'limpo' que exige a identificação correta do valor de maior frequência."}},"ES-083":{"cognitivo":{"motivo":"Cobrar, na forma invertida, que a moda é o valor mais frequente (25), e não o primeiro valor da série ordenada (22).","mede":"Estatística — Medidas de Tendência Central (cálculo da moda).","pegadinhaDesc":"A banca atribui a moda ao valor mínimo do conjunto, que na verdade aparece apenas uma vez.","ondeErra":"Confunde a moda com o menor valor do conjunto de dados, ignorando a contagem de frequências.","palavraCritica":"igual a 22 anos","tecnica":"O valor 22 aparece apenas uma vez no conjunto de dados (22, 25, 25, 25, 28, 30, 32, 35, 40) — não é, portanto, a moda. A moda correta é 25, valor que se repete 3 vezes, mais do que qualquer outro.","regraMental":"O menor valor do conjunto não é automaticamente a moda — é preciso contar as repetições de cada valor."},"comentario":{"resolucao":"ERRADO. A moda correta é 25 anos, e não 22. O valor 22 aparece apenas uma vez no conjunto de dados (22, 25, 25, 25, 28, 30, 32, 35, 40), ao passo que o valor 25 se repete 3 vezes, sendo o mais frequente.","fundamento":"Doutrina de Estatística — cálculo da moda (medida de tendência central).","macete":"Menor valor da lista ≠ moda. Moda é sempre o valor mais repetido.","erroComum":"Confundir a moda com o valor mínimo (ou qualquer valor que não seja o mais frequente) do conjunto de dados.","comoBancaPensa":"Atribui a moda a um valor extremo do conjunto para testar se o candidato realmente conta as frequências."}},"ES-084":{"cognitivo":{"motivo":"Cobrar o cálculo direto da média aritmética: soma dos valores dividida pela quantidade de observações.","mede":"Estatística — Medidas de Tendência Central (cálculo da média aritmética).","pegadinhaDesc":"A banca pode apresentar como média um valor que não corresponde à soma dividida pela quantidade correta de observações.","ondeErra":"Divide a soma dos valores por um número de observações diferente do real, ou erra a soma dos valores.","palavraCritica":"igual a 7","tecnica":"A média aritmética é a soma dos valores dividida pela quantidade de observações: (3 + 5 + 7 + 9 + 11) / 5 = 35 / 5 = 7.","regraMental":"Média = soma de tudo dividida pela quantidade de valores. Simples, mas sempre confira o denominador."},"comentario":{"resolucao":"CERTO. A soma das quantidades de armas apreendidas nas 5 operações é 3 + 5 + 7 + 9 + 11 = 35. Dividindo pela quantidade de operações (5), obtém-se a média aritmética: 35 / 5 = 7.","fundamento":"Doutrina de Estatística — cálculo da média aritmética (medida de tendência central).","macete":"Média = soma ÷ quantidade de valores. Confira sempre os dois números antes de dividir.","erroComum":"Errar a soma dos valores ou dividir por uma quantidade de observações incorreta.","comoBancaPensa":"Item 'limpo' que exige apenas o cálculo direto e correto da média aritmética."}},"ES-085":{"cognitivo":{"motivo":"Cobrar, na forma invertida, que a média aritmética correta do conjunto é 7, e não 9 (que é apenas um dos valores observados).","mede":"Estatística — Medidas de Tendência Central (cálculo da média aritmética).","pegadinhaDesc":"A banca apresenta um dos valores do próprio conjunto (9) como se fosse a média calculada.","ondeErra":"Confunde um valor individual do conjunto de dados com a média aritmética calculada a partir de todos eles.","palavraCritica":"igual a 9","tecnica":"A média aritmética é a soma dos valores dividida pela quantidade de observações: (3 + 5 + 7 + 9 + 11) / 5 = 35 / 5 = 7, e não 9 — que é apenas um dos cinco valores observados, não o resultado do cálculo da média.","regraMental":"Um valor do conjunto não é a média só porque está 'no meio' da lista — é preciso somar tudo e dividir."},"comentario":{"resolucao":"ERRADO. A média aritmética correta é 7, e não 9. A soma dos valores (3 + 5 + 7 + 9 + 11 = 35) dividida pela quantidade de operações (5) resulta em 35 / 5 = 7 — o valor 9 é apenas uma das observações, não o resultado da média.","fundamento":"Doutrina de Estatística — cálculo da média aritmética (medida de tendência central).","macete":"Nunca confundir um valor do conjunto com o resultado do cálculo da média.","erroComum":"Apontar um valor qualquer do conjunto de dados como sendo a própria média aritmética, sem realizar o cálculo.","comoBancaPensa":"Apresenta um valor real, porém individual, da série como se fosse o resultado do cálculo da média."}},"ES-086":{"cognitivo":{"motivo":"Cobrar a comparação entre o primeiro quartil (que reflete os valores mais baixos da distribuição) e a média amostral.","mede":"Estatística — Medidas de Tendência Central (quartis, comparação com a média).","pegadinhaDesc":"A banca pode afirmar o contrário, que o primeiro quartil é superior à média amostral.","ondeErra":"Não sabe calcular o primeiro quartil ou compara incorretamente seu valor com a média.","palavraCritica":"inferior à média amostral","tecnica":"Com os dados ordenados (50, 55, 60, 65, 70), a mediana é 60. O primeiro quartil (Q1) é a mediana da metade inferior dos dados (excluindo a mediana geral): {50, 55}, cuja média é (50 + 55) / 2 = 52,5. A média amostral é (50 + 55 + 60 + 65 + 70) / 5 = 300 / 5 = 60. Como 52,5 é menor que 60, o primeiro quartil é, de fato, inferior à média amostral.","regraMental":"Q1 reflete a 'metade de baixo' dos dados — costuma ficar abaixo da média quando a distribuição não é muito assimétrica para a esquerda."},"comentario":{"resolucao":"CERTO. O primeiro quartil (Q1) é calculado a partir da metade inferior dos dados ordenados (50, 55), resultando em 52,5. A média amostral é (50+55+60+65+70)/5 = 60. Como 52,5 é inferior a 60, o item está correto.","fundamento":"Doutrina de Estatística — quartis e média aritmética (medidas de posição e tendência central).","macete":"Q1 = mediana da metade inferior dos dados. Compare sempre com o resultado real da média, não com 'impressões'.","erroComum":"Inverter a comparação, afirmando que o primeiro quartil é superior à média amostral.","comoBancaPensa":"Item 'limpo' que exige o cálculo de duas medidas distintas (quartil e média) para uma comparação correta."}},"ES-087":{"cognitivo":{"motivo":"Cobrar, na forma invertida, que o primeiro quartil (52,5) é inferior — e não superior — à média amostral (60).","mede":"Estatística — Medidas de Tendência Central (quartis, comparação com a média).","pegadinhaDesc":"A banca inverte o resultado real da comparação entre o primeiro quartil e a média amostral.","ondeErra":"Calcula (ou assume) incorretamente que o primeiro quartil, por refletir 'apenas uma parte' dos dados, seria maior que a média.","palavraCritica":"superior à média amostral","tecnica":"O primeiro quartil (Q1) desse conjunto é 52,5 (média entre 50 e 55, a metade inferior dos dados ordenados). A média amostral é 60. Como 52,5 é MENOR que 60, o primeiro quartil é inferior — e não superior — à média amostral.","regraMental":"Confira sempre os dois valores calculados, sem assumir a comparação apenas por intuição."},"comentario":{"resolucao":"ERRADO. O primeiro quartil (Q1 = 52,5) é inferior — e não superior — à média amostral (60). O item inverte o resultado da comparação correta entre as duas medidas.","fundamento":"Doutrina de Estatística — quartis e média aritmética (medidas de posição e tendência central).","macete":"Refaça sempre os dois cálculos (Q1 e média) antes de aceitar qualquer comparação entre eles.","erroComum":"Assumir, sem calcular, que o primeiro quartil seria superior à média amostral.","comoBancaPensa":"Inverte o resultado de uma comparação numérica real para testar se o candidato de fato calcula, em vez de apenas estimar."}},"ES-088":{"cognitivo":{"motivo":"Cobrar que, em distribuições perfeitamente simétricas, média, mediana e moda tendem a coincidir.","mede":"Estatística — Medidas de Tendência Central (simetria da distribuição).","pegadinhaDesc":"A banca pode afirmar que essas três medidas nunca coincidem, ou que apenas duas delas são medidas de tendência central.","ondeErra":"Não sabe que a simetria perfeita da distribuição é justamente a condição que faz média, mediana e moda convergirem para o mesmo valor.","palavraCritica":"tendem a assumir o mesmo valor","tecnica":"Quando uma distribuição é perfeitamente simétrica (como a distribuição normal), as três principais medidas de tendência central — média aritmética, mediana e moda — tendem a coincidir no mesmo valor central, que corresponde também ao eixo de simetria da distribuição.","regraMental":"Simetria perfeita → média = mediana = moda. As três são medidas de tendência central."},"comentario":{"resolucao":"CERTO. Em uma distribuição perfeitamente simétrica, a média aritmética, a mediana e a moda tendem a assumir o mesmo valor, que corresponde ao eixo de simetria da distribuição — todas essas três medidas são classificadas como medidas de tendência central.","fundamento":"Doutrina de Estatística — medidas de tendência central e simetria de distribuições.","macete":"Distribuição simétrica: média = mediana = moda, todas coincidindo no centro.","erroComum":"Achar que essas três medidas nunca podem coincidir, ou que alguma delas não é medida de tendência central.","comoBancaPensa":"Item 'limpo' que reforça a relação central entre simetria e coincidência das três principais medidas."}},"ES-089":{"cognitivo":{"motivo":"Cobrar, na forma invertida, que em distribuições perfeitamente simétricas as três medidas coincidem, e não que a moda supera as demais.","mede":"Estatística — Medidas de Tendência Central (simetria da distribuição).","pegadinhaDesc":"A banca afirma que a moda é sempre superior às demais medidas e que a coincidência entre elas é rara.","ondeErra":"Confunde a relação entre média, mediana e moda em distribuições ASSIMÉTRICAS (onde de fato podem se ordenar) com a situação de simetria perfeita, na qual elas coincidem.","palavraCritica":"valor superior ... raramente coincidem","tecnica":"É justamente na distribuição perfeitamente simétrica que média, mediana e moda tendem a COINCIDIR no mesmo valor — a diferenciação entre essas medidas (com uma sendo maior que as outras) ocorre em distribuições ASSIMÉTRICAS, e não nas simétricas.","regraMental":"Simetria perfeita = as três coincidem. É a assimetria que separa média, mediana e moda em valores diferentes."},"comentario":{"resolucao":"ERRADO. Em uma distribuição perfeitamente simétrica, a moda NÃO tende a superar a média e a mediana — pelo contrário, as três medidas tendem a coincidir no mesmo valor. É nas distribuições assimétricas que essas medidas se distanciam entre si.","fundamento":"Doutrina de Estatística — medidas de tendência central e simetria de distribuições.","macete":"Simetria = coincidência das três medidas. Diferença entre elas é sinal de assimetria, não de simetria.","erroComum":"Achar que a simetria perfeita é a condição em que as medidas de tendência central mais se distanciam entre si.","comoBancaPensa":"Inverte a relação real entre simetria e coincidência das medidas de tendência central."}},"ES-090":{"cognitivo":{"motivo":"Cobrar que a igualdade entre média e mediana não garante, por si só, que a distribuição dos dados seja simétrica.","mede":"Estatística — Medidas de Tendência Central (relação entre média, mediana e simetria).","pegadinhaDesc":"A banca pode afirmar que, sempre que a média for igual à mediana, a distribuição será necessariamente simétrica.","ondeErra":"Confunde 'média igual à mediana' (condição necessária, mas não suficiente) com 'distribuição simétrica' (condição mais forte).","palavraCritica":"média igual à mediana ... de forma assimétrica","tecnica":"No conjunto {0, 0, 5, 7, 13}, a média é (0+0+5+7+13)/5 = 25/5 = 5, e a mediana (valor central após ordenação) também é 5 — logo, média = mediana = 5. No entanto, os desvios em torno desse valor central são -5, -5, 0, +2 e +8: não há simetria (os valores não se distribuem espelhados de forma equilibrada de ambos os lados do centro). Isso mostra que a igualdade entre média e mediana não implica, por si só, simetria da distribuição.","regraMental":"Média = mediana é necessário para simetria perfeita, mas não é suficiente — pode haver essa igualdade em distribuições assimétricas."},"comentario":{"resolucao":"CERTO. No conjunto {0, 0, 5, 7, 13}, tanto a média quanto a mediana são iguais a 5. Ainda assim, os valores não se distribuem de forma simétrica em torno desse centro (os desvios são -5, -5, 0, +2 e +8, sem espelhamento equilibrado) — a igualdade entre média e mediana não implica, portanto, simetria da distribuição.","fundamento":"Doutrina de Estatística — relação entre média, mediana e simetria de distribuições.","macete":"Média = mediana não garante simetria — é condição necessária, mas não suficiente.","erroComum":"Achar que toda vez que média e mediana coincidem, a distribuição dos dados é automaticamente simétrica.","comoBancaPensa":"Item 'limpo' que exige entender a diferença entre uma condição necessária e uma condição suficiente para a simetria."}},"ES-091":{"cognitivo":{"motivo":"Cobrar, na forma invertida, que a igualdade entre média e mediana não é condição suficiente para concluir simetria da distribuição.","mede":"Estatística — Medidas de Tendência Central (relação entre média, mediana e simetria).","pegadinhaDesc":"A banca generaliza indevidamente, tratando a igualdade entre média e mediana como prova definitiva de simetria.","ondeErra":"Não percebe que é possível construir conjuntos de dados assimétricos nos quais, ainda assim, média e mediana coincidam numericamente.","palavraCritica":"necessariamente ... simétrica","tecnica":"É possível ter conjuntos de dados em que a média seja numericamente igual à mediana, mas cuja distribuição seja assimétrica — por exemplo, {0, 0, 5, 7, 13}, em que ambas valem 5, mas os desvios em torno desse valor (-5, -5, 0, +2, +8) não são simétricos. A igualdade entre média e mediana, portanto, não permite concluir simetria de forma automática.","regraMental":"Média = mediana não garante simetria — sempre existem contraexemplos possíveis com dados assimétricos."},"comentario":{"resolucao":"ERRADO. A igualdade numérica entre média e mediana não permite concluir, necessariamente, que a distribuição seja simétrica. É possível haver conjuntos de dados assimétricos (como {0, 0, 5, 7, 13}, em que ambas valem 5) em que essa igualdade ocorre sem simetria real na distribuição.","fundamento":"Doutrina de Estatística — relação entre média, mediana e simetria de distribuições.","macete":"'Sempre que média = mediana, distribuição é simétrica' está sempre errado — existem contraexemplos.","erroComum":"Tratar a igualdade entre média e mediana como prova suficiente e automática de simetria da distribuição.","comoBancaPensa":"Generaliza uma condição necessária (mas não suficiente) como se fosse garantia absoluta de simetria."}},"ES-092":{"cognitivo":{"motivo":"Cobrar a recomposição de médias ao combinar dois grupos: a partir da soma total dos dois grupos, isolar a média do subgrupo desconhecido.","mede":"Estatística — Medidas de Tendência Central (recomposição de médias, problemas combinados).","pegadinhaDesc":"A banca pode apresentar um limiar de comparação inconsistente com o cálculo real da média dos novos policiais.","ondeErra":"Tenta estimar a média do subgrupo novo sem calcular corretamente as somas totais de idade antes e depois da admissão.","palavraCritica":"inferior a 30 anos","tecnica":"Soma das idades dos 8 policiais originais: 8 × 38 = 304 anos. Soma das idades do grupo combinado (12 policiais, média 35): 12 × 35 = 420 anos. Soma das idades dos 4 novos policiais: 420 − 304 = 116 anos. Média de idade dos novos: 116 / 4 = 29 anos — que é, de fato, inferior a 30.","regraMental":"Para recompor médias de grupos combinados: some totais (média × quantidade), subtraia o que já se sabe, e divida pelo restante."},"comentario":{"resolucao":"CERTO. A soma das idades dos 8 policiais originais é 8×38=304. A soma das idades do grupo combinado (12 policiais, média 35) é 12×35=420. A soma das idades dos 4 novos policiais é 420−304=116, resultando em uma média de 116/4=29 anos — inferior a 30, como afirma o item.","fundamento":"Doutrina de Estatística — recomposição de médias em grupos combinados (problemas de média ponderada).","macete":"Some os totais (média × n), subtraia o grupo conhecido, divida pelo grupo restante.","erroComum":"Tentar 'estimar' a média do novo grupo sem recompor corretamente as somas totais de idade envolvidas.","comoBancaPensa":"Item 'limpo' que exige o raciocínio completo de recomposição de médias a partir de somas totais."}},"ES-093":{"cognitivo":{"motivo":"Cobrar, na forma invertida, que a média correta dos 4 novos policiais (29 anos) é inferior — e não superior — a 30 anos.","mede":"Estatística — Medidas de Tendência Central (recomposição de médias, problemas combinados).","pegadinhaDesc":"A banca inverte o resultado real do cálculo, testando se o candidato apenas 'estima' em vez de calcular.","ondeErra":"Assume, sem calcular, que a média dos novos policiais deveria ser próxima ou superior à média geral combinada (35 anos).","palavraCritica":"superior a 30 anos","tecnica":"Recompondo as somas: 8 × 38 = 304 (grupo original); 12 × 35 = 420 (grupo combinado); 420 − 304 = 116 (soma dos 4 novos); 116 / 4 = 29 anos — inferior, e não superior, a 30 anos.","regraMental":"Não assuma a média do subgrupo desconhecido por intuição — sempre recomponha as somas totais antes de comparar."},"comentario":{"resolucao":"ERRADO. A média de idade dos 4 novos policiais é de 29 anos (calculada por 116/4, onde 116 = 420 − 304), e não superior a 30 anos como afirma o item — 29 é inferior a 30.","fundamento":"Doutrina de Estatística — recomposição de médias em grupos combinados (problemas de média ponderada).","macete":"Sempre recomponha as somas (média × n) antes de comparar — não assuma o resultado por intuição.","erroComum":"Estimar, sem calcular, que a média do subgrupo desconhecido deveria se aproximar da média geral do grupo combinado.","comoBancaPensa":"Inverte o resultado real do cálculo de recomposição de médias para testar se o candidato de fato resolve o problema."}},"ES-094":{"cognitivo":{"motivo":"Cobrar o cálculo do primeiro quartil em um conjunto com valores repetidos, usando a mediana da metade inferior dos dados.","mede":"Estatística — Medidas de Tendência Central (quartis, conjunto de dados com repetições).","pegadinhaDesc":"A banca pode atribuir ao primeiro quartil um valor da metade superior dos dados, em vez da metade inferior.","ondeErra":"Calcula o quartil a partir da metade errada dos dados (superior em vez de inferior), ou erra a mediana dessa metade.","palavraCritica":"igual a 2","tecnica":"Com os 10 valores já ordenados (1, 2, 2, 2, 2, 3, 4, 4, 4, 9), a metade inferior corresponde aos 5 primeiros valores: {1, 2, 2, 2, 2}. A mediana dessa metade (o valor central, 3º de 5) é 2. Logo, o primeiro quartil (Q1) do conjunto é 2.","regraMental":"Q1 = mediana da metade INFERIOR dos dados ordenados (excluindo, se necessário, a mediana geral)."},"comentario":{"resolucao":"CERTO. A metade inferior dos dados ordenados (1, 2, 2, 2, 2, 3, 4, 4, 4, 9) é {1, 2, 2, 2, 2}, cuja mediana (valor central) é 2. Esse é o valor do primeiro quartil (Q1) do conjunto.","fundamento":"Doutrina de Estatística — cálculo de quartis em conjuntos de dados com valores repetidos.","macete":"Q1 sempre vem da metade de baixo dos dados ordenados, nunca da metade de cima.","erroComum":"Calcular o quartil a partir da metade superior dos dados, em vez da metade inferior correspondente ao Q1.","comoBancaPensa":"Item 'limpo' que exige a correta segmentação dos dados ordenados para o cálculo do primeiro quartil."}},"ES-095":{"cognitivo":{"motivo":"Cobrar, na forma invertida, que o primeiro quartil (2) corresponde à metade inferior, e não à metade superior (onde está o valor 4).","mede":"Estatística — Medidas de Tendência Central (quartis, conjunto de dados com repetições).","pegadinhaDesc":"A banca calcula corretamente uma mediana, mas da metade ERRADA dos dados (a superior, que corresponderia ao terceiro quartil).","ondeErra":"Confunde o primeiro quartil (metade inferior) com o terceiro quartil (metade superior) do conjunto de dados.","palavraCritica":"igual a 4","tecnica":"O valor 4 é, na verdade, a mediana da metade SUPERIOR dos dados ordenados ({3, 4, 4, 4, 9}), que corresponde ao terceiro quartil (Q3), e não ao primeiro. O primeiro quartil (Q1) é calculado a partir da metade inferior ({1, 2, 2, 2, 2}), resultando em 2.","regraMental":"Metade de baixo = Q1. Metade de cima = Q3. Nunca trocar as duas metades entre si."},"comentario":{"resolucao":"ERRADO. O valor 4 corresponde ao terceiro quartil (Q3), calculado a partir da metade superior dos dados ({3, 4, 4, 4, 9}) — e não ao primeiro quartil (Q1), que é 2, calculado a partir da metade inferior ({1, 2, 2, 2, 2}).","fundamento":"Doutrina de Estatística — cálculo de quartis em conjuntos de dados com valores repetidos.","macete":"Metade de baixo → Q1. Metade de cima → Q3. Não confundir os dois quartis extremos.","erroComum":"Calcular corretamente um quartil, mas atribuí-lo ao rótulo errado (Q1 em vez de Q3, ou vice-versa).","comoBancaPensa":"Apresenta um valor real do conjunto (o Q3 correto), mas o rotula incorretamente como sendo o primeiro quartil."}},"ES-096":{"cognitivo":{"motivo":"Cobrar que a média é sensível a valores extremos (outliers), enquanto a mediana é uma medida robusta a esse tipo de distorção.","mede":"Estatística — Medidas de Tendência Central (sensibilidade a outliers, robustez da mediana).","pegadinhaDesc":"A banca pode afirmar que média e mediana são igualmente sensíveis a valores extremos.","ondeErra":"Não sabe que a mediana, por depender apenas da posição central dos dados ordenados, tende a não se alterar diante de um valor extremo isolado.","palavraCritica":"alteração significativa ... permanecerá igual a 4 ... maior sensibilidade da média","tecnica":"Antes da substituição: média = (3+4+4+5+6)/5 = 22/5 = 4,4; mediana = 4. Após substituir 6 por 60: média = (3+4+4+5+60)/5 = 76/5 = 15,2 (alteração significativa); mediana (dados ordenados: 3,4,4,5,60) permanece o valor central = 4 (inalterada). Isso demonstra que a média é sensível a outliers, e a mediana é robusta a eles.","regraMental":"Outlier distorce a média (que soma tudo), mas raramente move a mediana (que só olha a posição central)."},"comentario":{"resolucao":"CERTO. Antes da substituição, a média é 4,4 e a mediana é 4. Após substituir 6 por 60, a média salta para 15,2 (alteração significativa), enquanto a mediana permanece igual a 4 — evidenciando que a média é mais sensível a valores extremos (outliers) do que a mediana.","fundamento":"Doutrina de Estatística — sensibilidade das medidas de tendência central a valores extremos (outliers).","macete":"Outlier: média dispara, mediana quase não se move — por isso a mediana é preferida em dados com valores extremos.","erroComum":"Achar que média e mediana são igualmente afetadas pela presença de um valor discrepante no conjunto de dados.","comoBancaPensa":"Item 'limpo' que ilustra numericamente, com um exemplo concreto, a diferença de robustez entre média e mediana."}},"ES-097":{"cognitivo":{"motivo":"Cobrar, na forma invertida, que a mediana é robusta a outliers, ao contrário da média, que é sensível a eles.","mede":"Estatística — Medidas de Tendência Central (sensibilidade a outliers, robustez da mediana).","pegadinhaDesc":"A banca afirma que ambas as medidas reagem da mesma forma a um valor extremo, igualando indevidamente média e mediana.","ondeErra":"Ignora que a mediana, por depender apenas da posição central dos dados ordenados, não se altera com a simples troca de um valor extremo, ao contrário da média.","palavraCritica":"ambas as medidas são igualmente sensíveis ... mesma magnitude","tecnica":"Antes da substituição: média = 4,4; mediana = 4. Após substituir 6 por 60: média = 15,2 (alteração de mais de 10 pontos); mediana permanece 4 (nenhuma alteração). As duas medidas reagem de forma completamente diferente ao outlier — a média é muito mais sensível, e a mediana é robusta a esse tipo de distorção.","regraMental":"Nunca tratar média e mediana como igualmente sensíveis a outliers — a mediana é a medida robusta, a média não é."},"comentario":{"resolucao":"ERRADO. A mediana permanece igual a 4 mesmo após a substituição do valor 6 por 60, ao passo que a média salta de 4,4 para 15,2 — as duas medidas não reagem de forma igual ou proporcional a um valor extremo; a mediana é robusta a outliers, e a média não é.","fundamento":"Doutrina de Estatística — sensibilidade das medidas de tendência central a valores extremos (outliers).","macete":"Mediana é robusta a outliers; média não é — nunca tratá-las como igualmente sensíveis.","erroComum":"Achar que qualquer alteração em um valor do conjunto afeta média e mediana na mesma proporção.","comoBancaPensa":"Generaliza indevidamente a reação das duas medidas a um valor extremo, ignorando a robustez conhecida da mediana."}},"ES-098":{"cognitivo":{"motivo":"Fixar as condições que caracterizam um experimento binomial.","mede":"Modelo binomial — pressupostos.","pegadinhaDesc":"As quatro condições estão corretas; a banca costuma trocar 'constante' por 'variável'.","ondeErra":"Confunde com a hipergeométrica, em que p varia por não haver reposição.","palavraCritica":"independentes ... constante","tecnica":"Binomial: n fixo, provas independentes, dois resultados, p constante. Se p muda entre provas, é hipergeométrica.","regraMental":"Binomial = com reposição (p constante). Hipergeométrica = sem reposição."},"comentario":{"resolucao":"CERTO. São exatamente os pressupostos do modelo binomial: número fixo de ensaios (n), independência entre eles, dicotomia dos resultados (sucesso/fracasso) e probabilidade de sucesso p constante. A amostragem com reposição garante essa constância.","fundamento":"Modelo binomial — X ~ B(n, p).","macete":"n fixo + independência + 2 resultados + p constante.","erroComum":"Aplicar binomial a sorteios sem reposição.","comoBancaPensa":"Item correto que testa a distinção binomial × hipergeométrica."}},"ES-099":{"cognitivo":{"motivo":"Separar os momentos da binomial dos da Poisson.","mede":"Binomial — E(X) e Var(X).","pegadinhaDesc":"Acerta a esperança e atribui à binomial a igualdade média = variância, que é propriedade da Poisson.","ondeErra":"Transfere para a binomial a marca registrada da Poisson.","palavraCritica":"variância também é np","tecnica":"Var = np(1−p) = npq. Como q < 1, a variância é sempre MENOR que a média na binomial — é a Poisson que tem média igual à variância.","regraMental":"Binomial: média np, variância npq (menor). Poisson: iguais."},"comentario":{"resolucao":"ERRADO. A esperança está correta, E(X) = np, mas a variância é Var(X) = np(1 − p) = npq. Como 0 < q < 1, na binomial a variância é sempre INFERIOR à média. A igualdade entre média e variância é característica da distribuição de Poisson, não da binomial.","fundamento":"Modelo binomial — momentos.","macete":"Média np; variância npq.","erroComum":"Escrever Var(X) = np, confundindo com Poisson.","comoBancaPensa":"Acerta a parte fácil e cola na binomial a propriedade que identifica a Poisson."}},"ES-100":{"cognitivo":{"motivo":"Fixar a igualdade entre média e variância na Poisson.","mede":"Modelo de Poisson — momentos.","pegadinhaDesc":"Acerta a média e eleva a variância ao quadrado, quebrando a propriedade central do modelo.","ondeErra":"Aplica a intuição da variância como 'quadrado de algo' (herança do desvio padrão).","palavraCritica":"λ²","tecnica":"A marca da Poisson é E(X) = Var(X) = λ. Se a questão separar os dois valores, está errada.","regraMental":"Poisson: média = variância = λ."},"comentario":{"resolucao":"ERRADO. Na distribuição de Poisson, média e variância são ambas iguais a λ: E(X) = Var(X) = λ. Essa igualdade é justamente a característica que identifica o modelo. O desvio padrão, sim, é √λ.","fundamento":"Modelo de Poisson — X ~ Poisson(λ).","macete":"Poisson: média = variância.","erroComum":"Elevar λ ao quadrado na variância.","comoBancaPensa":"Ataca a propriedade mais distintiva do modelo, apostando na confusão com desvio padrão."}},"ES-101":{"cognitivo":{"motivo":"Fixar o contexto de aplicação da Poisson.","mede":"Modelo de Poisson — pressupostos.","pegadinhaDesc":"Descrição fiel do modelo de contagem em intervalo contínuo.","ondeErra":"Confunde com binomial, que conta sucessos em n provas fixas, não em intervalo.","palavraCritica":"intervalo fixo de tempo ou espaço","tecnica":"Binomial conta sucessos em n ensaios; Poisson conta ocorrências por unidade de tempo/espaço, sem n definido.","regraMental":"Poisson: quantos por hora/km/página."},"comentario":{"resolucao":"CERTO. A Poisson modela contagens de eventos raros e independentes em um intervalo fixo (tempo, área, volume), sob taxa média constante λ — como chamadas por hora ou defeitos por metro de tecido.","fundamento":"Modelo de Poisson — pressupostos.","macete":"Poisson conta ocorrências por unidade de tempo ou espaço.","erroComum":"Exigir número fixo de ensaios, como na binomial.","comoBancaPensa":"Item correto que separa contagem por intervalo de contagem por ensaios."}},"ES-102":{"cognitivo":{"motivo":"Fixar o critério que separa hipergeométrica de binomial.","mede":"Modelo hipergeométrico — pressupostos.","pegadinhaDesc":"Descrição correta; o candidato pode duvidar por associar 'dois resultados' automaticamente à binomial.","ondeErra":"Aplica binomial a sorteios sem reposição.","palavraCritica":"sem reposição","tecnica":"A pergunta decisiva é: houve reposição? Sem reposição em população finita → hipergeométrica.","regraMental":"Sem reposição = hipergeométrica."},"comentario":{"resolucao":"CERTO. Na hipergeométrica, as extrações ocorrem sem reposição em população finita de tamanho N com K sucessos; a cada retirada a composição muda, de modo que as provas são dependentes e p não é constante — exatamente o que a distingue da binomial.","fundamento":"Modelo hipergeométrico.","macete":"Sem reposição → hipergeométrica.","erroComum":"Usar binomial em amostragem sem reposição.","comoBancaPensa":"Item correto que cobra o critério de escolha entre os dois modelos."}},"ES-103":{"cognitivo":{"motivo":"Fixar o que a geométrica conta.","mede":"Modelo geométrico.","pegadinhaDesc":"Definição correta; a banca costuma trocar 'primeiro' por 'k-ésimo', que seria binomial negativa.","ondeErra":"Confunde com a binomial negativa (r-ésimo sucesso).","palavraCritica":"primeiro sucesso","tecnica":"Geométrica é o caso particular da binomial negativa com r = 1.","regraMental":"Geométrica: espera o 1º sucesso."},"comentario":{"resolucao":"CERTO. A geométrica conta os ensaios independentes de Bernoulli até o primeiro sucesso, com P(X = k) = (1 − p)^(k−1)·p. É o caso particular da binomial negativa em que se aguarda apenas um sucesso.","fundamento":"Modelo geométrico.","macete":"Geométrica = tempo de espera do 1º sucesso.","erroComum":"Confundir com binomial negativa.","comoBancaPensa":"Item correto que exige separar geométrica de binomial negativa."}},"ES-104":{"cognitivo":{"motivo":"Separar binomial negativa de geométrica.","mede":"Modelo binomial negativo.","pegadinhaDesc":"Reduz a binomial negativa ao seu caso particular, afirmando identidade total.","ondeErra":"Sabe que há parentesco entre as duas e conclui que são iguais.","palavraCritica":"idêntica ... em qualquer situação","tecnica":"A binomial negativa aguarda o r-ésimo sucesso; a geométrica é o caso r = 1. A relação é de particularização, não de identidade.","regraMental":"Geométrica ⊂ binomial negativa (r = 1)."},"comentario":{"resolucao":"ERRADO. A binomial negativa modela o número de ensaios até o r-ésimo sucesso. A geométrica é apenas o caso particular em que r = 1; para r > 1 as distribuições não coincidem.","fundamento":"Modelo binomial negativo (Pascal).","macete":"Binomial negativa: espera o r-ésimo sucesso.","erroComum":"Tratar as duas como sinônimas.","comoBancaPensa":"Usa a relação verdadeira de caso particular para afirmar identidade falsa."}},"ES-105":{"cognitivo":{"motivo":"Fixar os axiomas da função de probabilidade.","mede":"Variáveis aleatórias discretas.","pegadinhaDesc":"Condições corretas de uma função de probabilidade.","ondeErra":"Aceita soma diferente de 1 em tabelas de distribuição.","palavraCritica":"soma ... igual a 1","tecnica":"Toda questão que apresenta tabela de distribuição pede, antes de tudo, conferir se a soma fecha em 1.","regraMental":"Σp(x) = 1 e 0 ≤ p(x) ≤ 1."},"comentario":{"resolucao":"CERTO. São as duas condições que definem uma função de probabilidade de variável discreta: não negatividade limitada por 1 e soma unitária sobre todo o suporte.","fundamento":"Axiomas da função de probabilidade.","macete":"Soma sempre 1.","erroComum":"Não checar o fechamento da tabela.","comoBancaPensa":"Item correto que prepara para questões com parâmetro a determinar."}},"ES-106":{"cognitivo":{"motivo":"Fixar as propriedades básicas da normal.","mede":"Distribuição normal.","pegadinhaDesc":"Propriedades corretas e centrais do modelo.","ondeErra":"Duvida por lembrar que em distribuições assimétricas essas medidas divergem.","palavraCritica":"coincidem","tecnica":"Simetria perfeita implica igualdade das três medidas de tendência central — é o oposto do que ocorre na assimétrica.","regraMental":"Normal: média = mediana = moda."},"comentario":{"resolucao":"CERTO. A normal é simétrica em relação à média, tem forma de sino e apresenta coincidência entre média, mediana e moda. Assimetria e curtose de excesso são nulas.","fundamento":"Distribuição normal — propriedades.","macete":"Normal: as três medidas centrais no mesmo ponto.","erroComum":"Aplicar a divergência típica de distribuições assimétricas.","comoBancaPensa":"Item correto de fundamento, base para questões de padronização."}},"ES-107":{"cognitivo":{"motivo":"Fixar a fórmula correta de padronização.","mede":"Escore Z.","pegadinhaDesc":"Acerta os parâmetros da normal padrão e erra o denominador da padronização.","ondeErra":"Troca desvio padrão por variância no denominador.","palavraCritica":"divisão pela variância","tecnica":"Z = (X − μ)/σ. O denominador é o DESVIO PADRÃO, não a variância — só assim Z fica adimensional.","regraMental":"Z divide por sigma, não por sigma²."},"comentario":{"resolucao":"ERRADO. A normal padrão realmente tem média 0 e desvio padrão 1, mas a padronização é Z = (X − μ)/σ, ou seja, divide-se pelo DESVIO PADRÃO, não pela variância. Dividir por σ² não produziria escore com desvio padrão unitário.","fundamento":"Padronização — escore Z.","macete":"Z = (X − μ)/σ.","erroComum":"Usar σ² no denominador.","comoBancaPensa":"Mantém correta a parte fácil (média 0, DP 1) e altera o denominador da fórmula."}},"ES-108":{"cognitivo":{"motivo":"Fixar a correspondência correta da regra empírica 68-95-99,7.","mede":"Distribuição normal — dispersão.","pegadinhaDesc":"Usa um percentual verdadeiro da escala com o número errado de desvios, o que soa familiar.","ondeErra":"Lembra do 95% mas o associa ao primeiro sigma.","palavraCritica":"um desvio padrão","tecnica":"Memorize a escada pareada: 1σ ≈ 68%, 2σ ≈ 95%, 3σ ≈ 99,7%. O 95% é do SEGUNDO desvio.","regraMental":"68 – 95 – 99,7 para 1, 2 e 3 sigmas."},"comentario":{"resolucao":"ERRADO. Em um desvio padrão em torno da média (μ ± 1σ) concentram-se cerca de 68% das observações. Os 95% correspondem a μ ± 2σ, e aproximadamente 99,7% a μ ± 3σ.","fundamento":"Regra empírica (68-95-99,7).","macete":"2 sigmas ≈ 95%; 1 sigma ≈ 68%.","erroComum":"Deslocar o percentual em um sigma.","comoBancaPensa":"Aproveita que o candidato memoriza os percentuais sem parear com o número de desvios."}},"ES-109":{"cognitivo":{"motivo":"Ligar exponencial e Poisson e fixar a propriedade característica.","mede":"Distribuição exponencial.","pegadinhaDesc":"Ambas as afirmações são corretas e complementares.","ondeErra":"Não associa a exponencial ao processo de Poisson.","palavraCritica":"falta de memória","tecnica":"Poisson conta ocorrências no intervalo; a exponencial mede o tempo ENTRE elas. Falta de memória: P(X > s+t | X > s) = P(X > t).","regraMental":"Poisson conta; exponencial cronometra o intervalo."},"comentario":{"resolucao":"CERTO. Se as ocorrências seguem processo de Poisson com taxa λ, o tempo entre ocorrências consecutivas segue exponencial de parâmetro λ. A falta de memória significa que o tempo já decorrido não altera a probabilidade de espera adicional — é a única contínua com essa propriedade.","fundamento":"Distribuição exponencial — relação com Poisson.","macete":"Exponencial = tempo de espera, sem memória.","erroComum":"Dissociar exponencial de Poisson.","comoBancaPensa":"Item correto que cobra a ligação entre os dois modelos."}},"ES-110":{"cognitivo":{"motivo":"Fixar a variância da uniforme contínua.","mede":"Distribuição uniforme.","pegadinhaDesc":"A densidade constante está correta e o formato da variância é quase certo — só o divisor foi trocado.","ondeErra":"Lembra do quadrado da amplitude mas não do divisor 12.","palavraCritica":"/2","tecnica":"Densidade f(x) = 1/(b−a); média (a+b)/2; variância (b−a)²/12. O 2 aparece na média, o 12 na variância.","regraMental":"Uniforme: média divide por 2, variância divide por 12."},"comentario":{"resolucao":"ERRADO. A densidade é de fato constante, f(x) = 1/(b − a) no intervalo, mas a variância da uniforme contínua é (b − a)²/12, e não (b − a)²/2. O divisor 2 pertence à média, que é o ponto médio (a + b)/2.","fundamento":"Distribuição uniforme contínua.","macete":"Média sobre 2; variância sobre 12.","erroComum":"Trocar o divisor da variância pelo da média.","comoBancaPensa":"Mantém correta a primeira metade e altera apenas o denominador da fórmula."}},"ES-111":{"cognitivo":{"motivo":"Fixar a diferença essencial entre variáveis discretas e contínuas.","mede":"Variáveis aleatórias contínuas.","pegadinhaDesc":"Propriedade correta, mas contraintuitiva — o candidato tende a rejeitar.","ondeErra":"Transfere a lógica das discretas, em que P(X = x) > 0.","palavraCritica":"exatamente um valor pontual ... zero","tecnica":"Em contínuas, probabilidade é área sob a curva; um ponto tem largura zero, logo área zero. Por isso P(X ≤ a) = P(X < a).","regraMental":"Contínua: ponto tem probabilidade zero; só intervalo tem área."},"comentario":{"resolucao":"CERTO. Para variáveis contínuas, a probabilidade corresponde à área sob a função densidade em um intervalo; um único ponto delimita área nula, de modo que P(X = a) = 0. Consequência prática: incluir ou excluir o extremo não altera a probabilidade do intervalo.","fundamento":"Variáveis aleatórias contínuas — função densidade.","macete":"Ponto isolado: probabilidade zero.","erroComum":"Aplicar raciocínio de variável discreta.","comoBancaPensa":"Item correto e contraintuitivo, que separa quem entendeu densidade de quem decorou."}},"ES-112":{"cognitivo":{"motivo":"Fixar a regra da adição em sua forma geral.","mede":"Probabilidade — união de eventos.","pegadinhaDesc":"Fórmula geral correta, válida inclusive para eventos não excludentes.","ondeErra":"Omite o termo da interseção, que só é nulo em eventos mutuamente excludentes.","palavraCritica":"− P(A ∩ B)","tecnica":"Subtrai-se a interseção para não contar duas vezes. Se A e B são excludentes, P(A ∩ B) = 0 e a fórmula simplifica.","regraMental":"União: soma menos a interseção."},"comentario":{"resolucao":"CERTO. É a regra geral da adição: P(A ∪ B) = P(A) + P(B) − P(A ∩ B). O termo subtraído corrige a dupla contagem do espaço comum; em eventos mutuamente excludentes ele é zero.","fundamento":"Axiomas de probabilidade — regra da adição.","macete":"Sempre desconte a interseção.","erroComum":"Somar direto, tratando todos os eventos como excludentes.","comoBancaPensa":"Item correto que serve de base para pegadinhas sobre exclusividade."}},"ES-113":{"cognitivo":{"motivo":"Separar exclusividade mútua de independência.","mede":"Probabilidade — conceitos.","pegadinhaDesc":"Confunde dois conceitos distintos que a banca adora sobrepor.","ondeErra":"Trata 'não ocorrem juntos' como 'não se influenciam'.","palavraCritica":"necessariamente independentes","tecnica":"Excludentes: P(A∩B)=0. Independentes: P(A∩B)=P(A)·P(B). Com P(A),P(B) > 0, o produto é positivo — logo não pode ser zero. São incompatíveis.","regraMental":"Excludentes com prob. positiva são sempre DEPENDENTES."},"comentario":{"resolucao":"ERRADO. É o oposto: eventos mutuamente excludentes com probabilidades positivas são necessariamente DEPENDENTES. Se A ocorre, B não pode ocorrer, o que é a maior dependência possível. Formalmente, P(A ∩ B) = 0, mas P(A)·P(B) > 0, violando a condição de independência.","fundamento":"Probabilidade — independência e exclusividade.","macete":"Excludente ≠ independente; com prob. positiva, são opostos.","erroComum":"Tratar os dois conceitos como sinônimos.","comoBancaPensa":"Explora a confusão terminológica mais clássica da probabilidade."}},"ES-114":{"cognitivo":{"motivo":"Fixar a definição de probabilidade condicional.","mede":"Probabilidade condicional.","pegadinhaDesc":"Definição correta; a banca costuma inverter o denominador.","ondeErra":"Divide pela probabilidade de A em vez de B.","palavraCritica":"probabilidade de B","tecnica":"P(A|B) = P(A∩B)/P(B). O denominador é sempre o evento CONDICIONANTE, o que vem depois da barra.","regraMental":"Divide pelo que veio depois da barra."},"comentario":{"resolucao":"CERTO. Por definição, P(A|B) = P(A ∩ B)/P(B), para P(B) > 0. O condicionamento restringe o espaço amostral a B, e por isso o denominador é a probabilidade de B.","fundamento":"Probabilidade condicional.","macete":"Denominador é o evento condicionante.","erroComum":"Inverter e dividir por P(A).","comoBancaPensa":"Item correto que sustenta questões de Bayes."}},"ES-115":{"cognitivo":{"motivo":"Fixar a definição do erro tipo I e sua relação com α.","mede":"Teste de hipóteses — erros.","pegadinhaDesc":"Definição e associação corretas; a banca costuma inverter com o erro tipo II.","ondeErra":"Troca rejeição por aceitação, ou associa α ao erro tipo II.","palavraCritica":"rejeitar ... verdadeira","tecnica":"Tipo I é REJEIÇÃO INCORRETA (α). Tipo II é ACEITAÇÃO INCORRETA (β).","regraMental":"Tipo I rejeita o que era verdade; α é sua probabilidade."},"comentario":{"resolucao":"CERTO. O erro tipo I é a rejeição incorreta de H₀ verdadeira, e sua probabilidade é justamente o nível de significância α — os testes são construídos para controlar esse erro.","fundamento":"Teste de hipóteses — erros tipo I e II.","macete":"Tipo I = rejeição incorreta = α.","erroComum":"Inverter com o erro tipo II.","comoBancaPensa":"Item correto sobre o par de definições mais cobrado da inferência."}},"ES-116":{"cognitivo":{"motivo":"Cobrar o trade-off entre os dois tipos de erro.","mede":"Teste de hipóteses — relação α × β.","pegadinhaDesc":"Sugere ganho sem custo, ignorando a relação inversa entre α e β.","ondeErra":"Supõe que basta ser mais rigoroso para errar menos em tudo.","palavraCritica":"diminui simultaneamente","tecnica":"Com n fixo, α e β se movem em sentidos opostos. Reduzir os dois ao mesmo tempo exige AUMENTAR a amostra.","regraMental":"α desce, β sobe — salvo se n crescer."},"comentario":{"resolucao":"ERRADO. Com o tamanho da amostra fixo, α e β variam em sentidos opostos: ao reduzir o nível de significância, exige-se evidência mais forte para rejeitar H₀, o que aumenta a probabilidade de erro tipo II. Reduzir ambos simultaneamente só é possível aumentando o tamanho da amostra.","fundamento":"Teste de hipóteses — trade-off α × β.","macete":"Com n fixo, α e β são gangorra.","erroComum":"Achar que rigor maior reduz todos os erros.","comoBancaPensa":"Oferece um 'ganho duplo' que viola o trade-off fundamental do teste."}},"ES-117":{"cognitivo":{"motivo":"Corrigir a interpretação equivocada mais comum do p-valor.","mede":"Teste de hipóteses — nível descritivo.","pegadinhaDesc":"Inverte o condicionamento: o p-valor condiciona-se a H₀ verdadeira, não mede a probabilidade dela.","ondeErra":"Lê o p-valor como probabilidade da hipótese, e não dos dados.","palavraCritica":"probabilidade de a hipótese nula ser verdadeira","tecnica":"p-valor = P(dados tão ou mais extremos | H₀ verdadeira). É probabilidade DOS DADOS dado H₀, nunca de H₀.","regraMental":"p-valor condiciona a H₀; não mede H₀."},"comentario":{"resolucao":"ERRADO. O p-valor é a probabilidade de se observar um resultado tão ou mais extremo que o obtido, SUPONDO a hipótese nula verdadeira. Não é a probabilidade de H₀ ser verdadeira — a estatística clássica não atribui probabilidade a hipóteses. Rejeita-se H₀ quando o p-valor é inferior a α.","fundamento":"Teste de hipóteses — p-valor (nível descritivo).","macete":"p-valor mede os dados, não a hipótese.","erroComum":"Inverter o condicionamento.","comoBancaPensa":"Explora o erro de interpretação mais difundido da inferência clássica."}},"ES-118":{"cognitivo":{"motivo":"Fixar a definição de poder do teste.","mede":"Teste de hipóteses — poder.","pegadinhaDesc":"Definição correta; a banca costuma trocar β por α.","ondeErra":"Escreve 1 − α, confundindo com o nível de confiança.","palavraCritica":"erro do tipo II","tecnica":"Poder = 1 − β: probabilidade de rejeitar H₀ quando ela é de fato falsa. Não confundir com 1 − α, que é o nível de confiança.","regraMental":"Poder = 1 − β. Confiança = 1 − α."},"comentario":{"resolucao":"CERTO. O poder do teste é 1 − β, ou seja, a probabilidade de rejeitar corretamente uma hipótese nula falsa. Aumenta com o tamanho da amostra e com o afastamento entre o valor hipotético e o real.","fundamento":"Teste de hipóteses — poder.","macete":"Poder = 1 − β.","erroComum":"Confundir com o nível de confiança (1 − α).","comoBancaPensa":"Item correto que separa poder de confiança."}},"ES-119":{"cognitivo":{"motivo":"Fixar o que a não rejeição de H₀ significa — e o que não significa.","mede":"Teste de hipóteses — lógica da decisão.","pegadinhaDesc":"Converte ausência de evidência contrária em prova a favor.","ondeErra":"Lê 'aceitar H₀' como 'H₀ provada'.","palavraCritica":"equivale a demonstrar","tecnica":"O teste só controla o erro de rejeitar H₀ verdadeira (α). Não rejeitar pode significar apenas amostra pequena ou teste de baixo poder.","regraMental":"Não rejeitar ≠ provar. Falta de evidência não é evidência de falta."},"comentario":{"resolucao":"ERRADO. Não rejeitar H₀ significa apenas que a evidência amostral foi insuficiente para rejeitá-la ao nível de significância adotado — o que pode decorrer de amostra pequena ou baixo poder do teste. A hipótese nula nunca é provada; ela é apenas mantida por falta de evidência contrária.","fundamento":"Teste de hipóteses — lógica da decisão.","macete":"Não rejeitar não é provar.","erroComum":"Tratar a não rejeição como confirmação de H₀.","comoBancaPensa":"Explora a leitura intuitiva de 'aceitar a hipótese' como demonstração."}},"ES-120":{"cognitivo":{"motivo":"Fixar o campo de aplicação do qui-quadrado.","mede":"Teste qui-quadrado.","pegadinhaDesc":"Descrição correta; a banca costuma afirmar que exige variáveis quantitativas.","ondeErra":"Supõe que todo teste estatístico requer variáveis numéricas.","palavraCritica":"qualitativas ... observadas ... esperadas","tecnica":"Qui-quadrado trabalha com CONTAGENS em categorias. A estatística soma (O − E)²/E sobre as células.","regraMental":"Qui-quadrado: variável qualitativa, compara observado com esperado."},"comentario":{"resolucao":"CERTO. O qui-quadrado de independência avalia associação entre duas variáveis qualitativas em tabela de contingência, confrontando frequências observadas e esperadas sob a hipótese de independência, pela soma de (O − E)²/E.","fundamento":"Teste qui-quadrado de independência.","macete":"Qualitativas + contagens = qui-quadrado.","erroComum":"Exigir variáveis quantitativas.","comoBancaPensa":"Item correto que fixa o único teste do edital voltado a dados categóricos."}},"ES-121":{"cognitivo":{"motivo":"Fixar a relação entre confiança e amplitude.","mede":"Estimação intervalar.","pegadinhaDesc":"Inverte a relação: mais confiança exige intervalo mais largo, não mais estreito.","ondeErra":"Associa 'melhor' a 'mais preciso' e conclui que ganha nos dois.","palavraCritica":"menor amplitude","tecnica":"Mais confiança → maior valor crítico → intervalo mais LARGO. Só se ganha precisão e confiança ao mesmo tempo aumentando n.","regraMental":"Mais confiança, mais largo. Para estreitar sem perder confiança, aumente n."},"comentario":{"resolucao":"ERRADO. É o contrário: elevar o nível de confiança (de 95% para 99%, por exemplo) exige valor crítico maior e, portanto, intervalo MAIS AMPLO. Só é possível estreitar o intervalo mantendo a confiança aumentando o tamanho da amostra ou reduzindo a variabilidade.","fundamento":"Estimação intervalar — confiança × precisão.","macete":"Mais confiança = intervalo mais largo.","erroComum":"Supor ganho simultâneo de confiança e precisão.","comoBancaPensa":"Oferece um ganho sem custo, invertendo o trade-off do intervalo."}},"ES-122":{"cognitivo":{"motivo":"Corrigir a interpretação frequentista do intervalo de confiança.","mede":"Estimação intervalar — interpretação.","pegadinhaDesc":"Atribui probabilidade a um parâmetro fixo e a um intervalo já observado.","ondeErra":"Lê a confiança como probabilidade do parâmetro, e não do procedimento.","palavraCritica":"daquele intervalo já calculado","tecnica":"Na inferência clássica o parâmetro é fixo; o que varia é o intervalo. A confiança é do MÉTODO: em 95% das amostras, o intervalo conteria o parâmetro.","regraMental":"Confiança é do procedimento, não do intervalo específico."},"comentario":{"resolucao":"ERRADO. Na abordagem clássica, o parâmetro é uma constante desconhecida e o intervalo já calculado ou o contém ou não. A confiança de 95% refere-se ao procedimento: se o processo de amostragem fosse repetido muitas vezes, cerca de 95% dos intervalos construídos conteriam o parâmetro.","fundamento":"Estimação intervalar — interpretação frequentista.","macete":"95% dos intervalos, não 95% de chance neste.","erroComum":"Atribuir probabilidade ao parâmetro.","comoBancaPensa":"Explora a interpretação intuitiva porém incorreta do intervalo."}},"ES-123":{"cognitivo":{"motivo":"Fixar a definição de não viés.","mede":"Estimação pontual — propriedades.","pegadinhaDesc":"Definição correta e formal.","ondeErra":"Confunde não viés com consistência ou eficiência.","palavraCritica":"esperança ... igual ao parâmetro","tecnica":"Não viés: E(estimador) = parâmetro. Consistência: converge com n → ∞. Eficiência: menor variância.","regraMental":"Não viesado acerta na média."},"comentario":{"resolucao":"CERTO. Um estimador é não viesado (não tendencioso) quando sua esperança coincide com o parâmetro. A média amostral é estimador não viesado da média populacional; a variância amostral com denominador n − 1 é não viesada da variância populacional.","fundamento":"Estimação pontual — não viés.","macete":"Não viesado: acerta na média.","erroComum":"Confundir com consistência.","comoBancaPensa":"Item correto sobre a propriedade mais cobrada de estimadores."}},"ES-124":{"cognitivo":{"motivo":"Fixar o critério que define amostragem probabilística.","mede":"Amostragem — classificação.","pegadinhaDesc":"Critério correto e sua consequência inferencial.","ondeErra":"Confunde com amostragem por conveniência ou por julgamento.","palavraCritica":"conhecida e não nula","tecnica":"Sem probabilidade conhecida de seleção não há como calcular erro amostral — por isso a não probabilística não permite inferência formal.","regraMental":"Probabilística = todos têm chance conhecida e positiva."},"comentario":{"resolucao":"CERTO. A amostragem probabilística exige que cada elemento tenha probabilidade conhecida e maior que zero de integrar a amostra, condição que viabiliza o cálculo do erro amostral e a inferência para a população. As modalidades não probabilísticas (conveniência, julgamento, cotas) não atendem a esse requisito.","fundamento":"Amostragem probabilística × não probabilística.","macete":"Probabilística: chance conhecida e positiva para todos.","erroComum":"Tratar amostra grande como sinônimo de probabilística.","comoBancaPensa":"Item correto que fundamenta a distinção entre os dois grupos de técnicas."}},"ES-125":{"cognitivo":{"motivo":"Separar as duas técnicas probabilísticas mais confundidas.","mede":"Amostragem — estratificada e conglomerados.","pegadinhaDesc":"Ambas as descrições corretas, inclusive quanto à homogeneidade interna.","ondeErra":"Inverte a homogeneidade ou supõe que na estratificada se sorteiam estratos.","palavraCritica":"homogêneos ... heterogêneos","tecnica":"Estrato: homogêneo dentro, e TODOS entram. Conglomerado: heterogêneo dentro (mini-população), e só ALGUNS são sorteados.","regraMental":"Estrato: todos participam. Conglomerado: sorteia-se o grupo."},"comentario":{"resolucao":"CERTO. Na estratificada busca-se homogeneidade interna nos estratos (e heterogeneidade entre eles), retirando-se elementos de cada estrato. Na amostragem por conglomerados, cada grupo idealmente reproduz a população (heterogêneo internamente) e sorteiam-se conglomerados inteiros, o que reduz custo mas tende a elevar o erro amostral.","fundamento":"Amostragem estratificada e por conglomerados.","macete":"Estrato: homogêneo e todos entram. Conglomerado: heterogêneo e sorteia-se o grupo.","erroComum":"Inverter a homogeneidade interna das duas técnicas.","comoBancaPensa":"Item correto que cobra a distinção integral entre as duas."}},"ES-126":{"cognitivo":{"motivo":"Fixar a classificação da amostragem sistemática.","mede":"Amostragem — classificação das técnicas.","pegadinhaDesc":"Usa a regularidade do passo como argumento para negar a natureza probabilística.","ondeErra":"Associa 'regra fixa' a 'sem sorteio', esquecendo que o ponto de partida é aleatório.","palavraCritica":"não probabilística","tecnica":"É probabilística porque o primeiro elemento é sorteado, o que dá a todos chance conhecida de seleção. Não probabilísticas são conveniência, julgamento e cotas.","regraMental":"Sistemática: sorteia o começo, depois anda de k em k — é probabilística."},"comentario":{"resolucao":"ERRADO. A amostragem sistemática é PROBABILÍSTICA: define-se o intervalo k = N/n, sorteia-se aleatoriamente o primeiro elemento entre os k iniciais e selecionam-se os demais de k em k. A aleatoriedade do ponto de partida garante probabilidade conhecida de seleção. São não probabilísticas as amostragens por conveniência, por julgamento e por cotas. Ressalva: a técnica pode gerar viés se a lista apresentar periodicidade coincidente com o intervalo.","fundamento":"Amostragem sistemática — classificação.","macete":"Início sorteado ⇒ probabilística.","erroComum":"Considerá-la não probabilística pela regularidade do passo.","comoBancaPensa":"Oferece um argumento plausível (regra fixa) para uma classificação errada."}},"ES-127":{"cognitivo":{"motivo":"Fixar o alcance do teorema central do limite.","mede":"Distribuições amostrais — TCL.","pegadinhaDesc":"Enunciado correto, inclusive na parte que dispensa a normalidade da população.","ondeErra":"Acredita que o TCL exige população normal.","palavraCritica":"ainda que a população ... não siga distribuição normal","tecnica":"O TCL fala da distribuição da MÉDIA AMOSTRAL, não dos dados. É o que autoriza usar a normal em amostras grandes de populações quaisquer.","regraMental":"TCL normaliza a média, não a população."},"comentario":{"resolucao":"CERTO. O teorema central do limite garante que, para n suficientemente grande, a distribuição da média amostral tende à normal, independentemente da distribuição da população de origem (desde que a variância seja finita). É esse resultado que sustenta a inferência baseada na normal em amostras grandes.","fundamento":"Teorema central do limite.","macete":"TCL: a média fica normal, mesmo com população torta.","erroComum":"Exigir população normal para aplicar o TCL.","comoBancaPensa":"Item correto sobre o teorema mais cobrado da inferência."}},"ES-128":{"cognitivo":{"motivo":"Fixar a fórmula do erro padrão.","mede":"Distribuições amostrais — erro padrão.","pegadinhaDesc":"Omite a raiz quadrada, exagerando a redução do erro com o aumento de n.","ondeErra":"Esquece que a divisão é por √n, não por n.","palavraCritica":"pelo tamanho da amostra","tecnica":"Erro padrão = σ/√n. Para reduzir o erro pela metade é preciso QUADRUPLICAR a amostra.","regraMental":"Divide por raiz de n."},"comentario":{"resolucao":"ERRADO. O erro padrão da média é σ/√n — divide-se pela RAIZ QUADRADA do tamanho da amostra, não por n. É por isso que ganhos de precisão são cada vez mais caros: reduzir o erro à metade exige amostra quatro vezes maior.","fundamento":"Distribuição amostral da média — erro padrão.","macete":"σ sobre raiz de n.","erroComum":"Dividir por n.","comoBancaPensa":"Suprime a raiz, um dos erros de fórmula mais explorados."}},"ES-129":{"cognitivo":{"motivo":"Delimitar o que o coeficiente de Pearson mede.","mede":"Correlação linear.","pegadinhaDesc":"Acerta o intervalo e generaliza indevidamente a interpretação do valor nulo.","ondeErra":"Toma 'sem correlação linear' por 'sem relação alguma'.","palavraCritica":"qualquer relação","tecnica":"Pearson mede apenas relação LINEAR. Uma relação perfeitamente quadrática pode apresentar r ≈ 0.","regraMental":"r ≈ 0 afasta reta, não afasta curva."},"comentario":{"resolucao":"ERRADO. O intervalo de −1 a 1 está correto, mas r próximo de zero indica ausência de relação LINEAR, e não de qualquer relação. Variáveis com associação não linear forte (parabólica, por exemplo) podem apresentar coeficiente de Pearson próximo de zero.","fundamento":"Coeficiente de correlação de Pearson.","macete":"Pearson só enxerga reta.","erroComum":"Concluir independência a partir de r ≈ 0.","comoBancaPensa":"Amplia a conclusão para além do que o coeficiente mede."}},"ES-130":{"cognitivo":{"motivo":"Fixar a interpretação do R².","mede":"Regressão linear — R².","pegadinhaDesc":"Interpretação correta do coeficiente.","ondeErra":"Confunde R² com o coeficiente angular ou com o próprio r.","palavraCritica":"proporção da variabilidade","tecnica":"Na regressão simples, R² é o quadrado de r e varia de 0 a 1 — sempre não negativo, ao contrário de r.","regraMental":"R² = quanto da variação Y o modelo explica."},"comentario":{"resolucao":"CERTO. O R² expressa a fração da variabilidade total da variável dependente explicada pela regressão, variando de 0 a 1. Na regressão linear simples equivale ao quadrado do coeficiente de correlação de Pearson.","fundamento":"Regressão linear — coeficiente de determinação.","macete":"R² = r² na regressão simples.","erroComum":"Confundir com o coeficiente angular.","comoBancaPensa":"Item correto sobre a medida de ajuste mais cobrada."}},"ES-131":{"cognitivo":{"motivo":"Separar associação de causalidade.","mede":"Correlação — interpretação.","pegadinhaDesc":"Converte medida de associação em prova de causa.","ondeErra":"Toma correlação alta como demonstração causal.","palavraCritica":"suficiente ... causa","tecnica":"Correlação pode decorrer de terceira variável (confundidora), coincidência ou causalidade reversa. Causalidade exige delineamento adequado.","regraMental":"Correlação não implica causalidade."},"comentario":{"resolucao":"ERRADO. Correlação mede associação, não causa. A relação observada pode resultar de variável confundidora, de causalidade em sentido inverso ou de mera coincidência (correlação espúria). A inferência causal exige delineamento experimental ou controle estatístico adequado.","fundamento":"Correlação × causalidade.","macete":"Correlação não prova causa.","erroComum":"Inferir causalidade de coeficiente alto.","comoBancaPensa":"Item clássico que testa rigor interpretativo."}},"ES-132":{"cognitivo":{"motivo":"Mostrar propriedade matemática genuinamente universal.","mede":"Modelo de Poisson.","pegadinhaDesc":"Duplo termo absoluto ('qualquer' e 'sempre') num enunciado que, ainda assim, é verdadeiro.","ondeErra":"Marca ERRADO pelo acúmulo de palavras absolutas.","palavraCritica":"qualquer ... sempre","tecnica":"Em matemática, propriedade demonstrada vale sempre. Na Poisson, E(X) = Var(X) = λ por definição do modelo.","regraMental":"Poisson: média = variância, sem exceção."},"comentario":{"resolucao":"CERTO. Para X ~ Poisson(λ), demonstra-se que E(X) = Var(X) = λ, qualquer que seja o valor de λ. É propriedade definidora do modelo, não uma aproximação.","fundamento":"Distribuição de Poisson — momentos.","macete":"Poisson: média = variância.","erroComum":"Rejeitar por conter 'qualquer' e 'sempre'.","comoBancaPensa":"Usa termos absolutos em afirmação matematicamente verdadeira."}},"ES-133":{"cognitivo":{"motivo":"Fixar axioma que não admite exceção.","mede":"Axiomas de probabilidade.","pegadinhaDesc":"'Toda' e 'necessariamente' num enunciado verdadeiro por definição.","ondeErra":"Reage aos termos absolutos em vez de checar o axioma.","palavraCritica":"necessariamente","tecnica":"É condição de existência da função de probabilidade: se a soma não fecha em 1, a distribuição não é válida.","regraMental":"Σp(x) = 1 sempre, senão não é distribuição."},"comentario":{"resolucao":"CERTO. A normalização é axioma da função de probabilidade: a soma sobre todo o suporte deve ser exatamente 1. Distribuição cuja soma difere de 1 simplesmente não é válida.","fundamento":"Axiomas de Kolmogorov — normalização.","macete":"Soma sempre 1.","erroComum":"Marcar ERRADO por causa de 'toda'.","comoBancaPensa":"Aplica termo absoluto a axioma, que por natureza não tem exceção."}},"ES-134":{"cognitivo":{"motivo":"Reforçar propriedade universal da normal.","mede":"Distribuição normal — simetria.","pegadinhaDesc":"Termos absolutos em propriedade que de fato vale para toda a família normal.","ondeErra":"Confunde com distribuições assimétricas e rejeita o 'toda'.","palavraCritica":"Toda ... qualquer","tecnica":"O desvio padrão altera a dispersão (largura do sino), nunca a simetria. Assimetria da normal é sempre zero.","regraMental":"Normal é sempre simétrica; σ muda a largura, não a forma."},"comentario":{"resolucao":"CERTO. A simetria em torno da média é característica de toda a família normal; o desvio padrão determina a dispersão (curva mais achatada ou mais estreita), mas o coeficiente de assimetria permanece zero.","fundamento":"Distribuição normal — propriedades.","macete":"σ muda a largura, não a simetria.","erroComum":"Rejeitar por causa do 'toda'.","comoBancaPensa":"Termos absolutos aplicados a propriedade universal."}},"ES-135":{"cognitivo":{"motivo":"Fixar o critério definidor, que por ser definição não admite exceção.","mede":"Amostragem probabilística.","pegadinhaDesc":"Duplo termo totalizante numa afirmação que é a própria definição do conceito.","ondeErra":"Supõe exceção onde se está diante de uma definição.","palavraCritica":"toda ... todos","tecnica":"Definição não comporta contraexemplo: se algum elemento tivesse probabilidade nula ou desconhecida, a amostragem deixaria de ser probabilística.","regraMental":"Probabilística = todos com chance conhecida e positiva, por definição."},"comentario":{"resolucao":"CERTO. É a própria definição de amostragem probabilística: probabilidade conhecida e não nula de seleção para todos os elementos, condição que viabiliza o cálculo do erro amostral. Se algum elemento não pudesse ser sorteado, tratar-se-ia de amostragem não probabilística.","fundamento":"Amostragem probabilística — definição.","macete":"É definição, não regra com exceção.","erroComum":"Buscar contraexemplo para uma definição.","comoBancaPensa":"Usa termo absoluto em enunciado que é definição conceitual."}},"ES-136":{"cognitivo":{"motivo":"Fixar a definição de mediana e sua robustez.","mede":"Medidas de tendência central.","pegadinhaDesc":"Definição e propriedade corretamente atribuídas.","ondeErra":"Confunde com moda ou atribui a robustez à média.","palavraCritica":"menos sensível a valores extremos","tecnica":"A mediana depende da POSIÇÃO, não dos valores; por isso outlier não a desloca. A média usa todos os valores e é arrastada por extremos.","regraMental":"Outlier mexe na média, não na mediana."},"comentario":{"resolucao":"CERTO. A mediana é o valor central dos dados ordenados e, por depender apenas da posição, resiste a valores extremos — motivo pelo qual é preferida à média em distribuições assimétricas, como as de renda.","fundamento":"Estatística descritiva — medidas de tendência central.","macete":"Mediana é robusta a outlier.","erroComum":"Atribuir a robustez à média.","comoBancaPensa":"Definição correta acompanhada da propriedade que a justifica."}},"ES-137":{"cognitivo":{"motivo":"Separar as duas técnicas pelo objetivo.","mede":"Correlação e regressão.","pegadinhaDesc":"Objetivos corretamente atribuídos.","ondeErra":"Usa os termos como sinônimos.","palavraCritica":"mede ... estabelece um modelo","tecnica":"Correlação responde 'quão associadas?'; regressão responde 'quanto muda Y se X mudar?'. Só a regressão prevê.","regraMental":"Correlação mede; regressão prevê."},"comentario":{"resolucao":"CERTO. A correlação quantifica intensidade e sentido da associação (r entre −1 e 1); a regressão ajusta um modelo (na forma simples, uma reta) que permite estimar a variável dependente a partir da explicativa.","fundamento":"Correlação e regressão linear.","macete":"Correlação mede, regressão prevê.","erroComum":"Tratar como sinônimos.","comoBancaPensa":"Par correto entre técnicas complementares."}}});
